    FIXED_HEADER = 16
    RECORD_TYPES = {
        1: "BEGIN",
        2: "COMMIT",
        3: "ROLLBACK",
        40: "INSERT",
        41: "DELETE",
        42: "BEFORE_UPDATE",
        43: "AFTER_UPDATE",
        62: "DISCARD",
        119: "TRUNCATE",
        200: "METADATA",
        201: "TIMEOUT",
        202: "ERROR",
    }
    _OP_TYPES = {40, 41, 42, 43}
    CDC_ROUTINE_DATABASE = "syscdcv1"


    def cdc_routine(name: str) -> str:
        # Docstring: Return the cross-database name of an installed Informix CDC routine.

        if not name.startswith("cdc_") or not name.replace("_", "").isalnum():
            raise CdcProtocolError(f"invalid CDC routine name {name!r}")
        return f"{CDC_ROUTINE_DATABASE}:informix.{name}"


    def metadata_column_names(payload: bytes, encoding: str = "utf-8") -> tuple[str, ...]:
        # Docstring: Extract CDC metadata column names while ignoring commas in type arguments.

        text = payload.rstrip(b"\0 \t\r\n").decode(encoding)
        fields: list[str] = []
        start = depth = 0
        for index, character in enumerate(text):
            if character == "(":
                depth += 1
            elif character == ")":
                if depth == 0:
                    raise CdcProtocolError("unbalanced CDC metadata type")
                depth -= 1
            elif character == "," and depth == 0:
                fields.append(text[start:index].strip())
                start = index + 1
        if depth:
            raise CdcProtocolError("unbalanced CDC metadata type")
        fields.append(text[start:].strip())
        names = tuple(field.split(None, 1)[0] for field in fields if field)
        if not names or len(names) != len(set(names)):
            raise CdcProtocolError("CDC metadata has missing or duplicate column names")
        return names


    class CdcProtocolError(ValueError):
        pass


    class UnsupportedCdcType(CdcProtocolError):
        pass


    class OpenTransactionRecords:
        # Docstring: Count only data records still held by currently open transactions.

        def __init__(self) -> None:
            self._sequences: dict[int, list[int]] = {}

        def __bool__(self) -> bool:
            return bool(self._sequences)

        @property
        def buffered(self) -> int:
            return sum(len(values) for values in self._sequences.values())

        def begin(self, tx_id: int) -> None:
            if tx_id in self._sequences:
                raise CdcProtocolError(f"duplicate CDC BEGIN for transaction {tx_id}")
            self._sequences[tx_id] = []

        def append(self, tx_id: int, lsn: int) -> None:
            if tx_id not in self._sequences:
                raise CdcProtocolError(f"CDC data for unknown transaction {tx_id}")
            self._sequences[tx_id].append(lsn)

        def discard(self, tx_id: int, lsn: int) -> None:
            if tx_id not in self._sequences:
                raise CdcProtocolError(f"CDC DISCARD for unknown transaction {tx_id}")
            self._sequences[tx_id] = [value for value in self._sequences[tx_id] if value < lsn]

        def finish(self, tx_id: int) -> None:
            if tx_id not in self._sequences:
                raise CdcProtocolError(f"CDC completion for unknown transaction {tx_id}")
            del self._sequences[tx_id]


    def validate_snapshot_arity(after: Sequence[Any] | None, primary_keys: Sequence[str]) -> None:
        if after is not None and len(after) != len(primary_keys):
            raise CdcProtocolError("Snapshot primary-key offset has the wrong arity")


    # No generated __repr__ or __eq__: nothing prints descriptors or compares them by
    # value, and the merged deployment pickles every generated method.
    @dataclass(frozen=True, eq=False, repr=False)
    class ColumnDescriptor:
        name: str
        type_name: str
        length: int = 0
        precision: int | None = None
        scale: int | None = None
        encoding: str = "utf-8"


    class CdcFrameParser:
        # Docstring: Incremental bounded parser preserving partial frames between reads.

        def __init__(self, max_frame_bytes: int = 16 * 1024 * 1024) -> None:
            if max_frame_bytes < FIXED_HEADER:
                raise ValueError("max_frame_bytes must be at least 16")
            self.max_frame_bytes = max_frame_bytes
            self._buffer = bytearray()

        @property
        def buffered_bytes(self) -> int:
            return len(self._buffer)

        def feed(self, data: bytes | bytearray | memoryview) -> list[bytes]:
            self._buffer.extend(data)
            frames = []
            while len(self._buffer) >= FIXED_HEADER:
                header_size, payload_size = struct.unpack_from(">II", self._buffer)
                if header_size < FIXED_HEADER:
                    raise CdcProtocolError(f"invalid CDC header size {header_size}")
                total = header_size + payload_size
                if total < header_size or total > self.max_frame_bytes:
                    raise CdcProtocolError(f"CDC frame size {total} exceeds configured bound")
                if len(self._buffer) < total:
                    break
                frames.append(bytes(self._buffer[:total]))
                del self._buffer[:total]
            if len(self._buffer) > self.max_frame_bytes:
                raise CdcProtocolError("unterminated CDC frame exceeds configured bound")
            return frames


    def decode_frame(
        frame: bytes,
        columns_by_label: dict[int, tuple[ColumnDescriptor, ...]],
        *,
        null_byte: str = "keep",
    ) -> dict:
        if len(frame) < FIXED_HEADER:
            raise CdcProtocolError("truncated CDC fixed header")
        header_size, payload_size, reserved, kind = struct.unpack_from(">IIII", frame)
        total = header_size + payload_size
        if header_size < FIXED_HEADER or total != len(frame):
            raise CdcProtocolError("CDC frame length does not match header")
        op = RECORD_TYPES.get(kind)
        if op is None:
            raise CdcProtocolError(f"unknown CDC record type {kind}")
        header = memoryview(frame)[FIXED_HEADER:header_size]
        payload = memoryview(frame)[header_size:]
        record: dict[str, Any] = {"op": op, "reserved": reserved}
        if kind in _OP_TYPES:
            _require_header(header, 16, op)
            lsn, tx_id, label = struct.unpack_from(">Qii", header)
            record.update(lsn=lsn, tx_id=tx_id, label=label)
            columns = columns_by_label.get(label)
            if columns is None:
                raise CdcProtocolError(f"operation references unknown capture label {label}")
            record["row"] = decode_row(payload, columns, null_byte=null_byte)
        elif kind == 1:
            _require_header(header, 24, op)
            lsn, tx_id, timestamp, user_id = struct.unpack_from(">Qiqi", header)
            record.update(lsn=lsn, tx_id=tx_id, timestamp=timestamp, user_id=user_id)
        elif kind == 2:
            _require_header(header, 20, op)
            lsn, tx_id, timestamp = struct.unpack_from(">Qiq", header)
            record.update(lsn=lsn, tx_id=tx_id, timestamp=timestamp)
        elif kind in {3, 62}:
            _require_header(header, 12, op)
            lsn, tx_id = struct.unpack_from(">Qi", header)
            record.update(lsn=lsn, tx_id=tx_id)
        elif kind == 119:
            _require_header(header, 16, op)
            lsn, tx_id, label = struct.unpack_from(">Qii", header)
            record.update(lsn=lsn, tx_id=tx_id, user_id=label, capture_label=label)
        elif kind == 200:
            _require_header(header, 4, op)
            record.update(label=struct.unpack_from(">i", header)[0], metadata=bytes(payload))
        elif kind == 201:
            _require_header(header, 8, op)
            record["lsn"] = struct.unpack_from(">Q", header)[0]
        elif kind == 202:
            _require_header(header, 8, op)
            record["flags"], record["error"] = struct.unpack_from(">ii", header)
        if payload and kind not in _OP_TYPES and kind != 200:
            record["payload"] = bytes(payload)
        return record


    def frame_log_file(frame: bytes) -> int | None:
        # Docstring: Return the logical log file a data frame's LSN names, when discoverable.
        #
        # Only operation frames carry an LSN, and a frame that failed to decode may be
        # malformed in other ways, so this reports ``None`` rather than raising when the
        # position cannot be read. Callers use it to attribute an undecodable record to
        # the log file it came from.

        if len(frame) < FIXED_HEADER:
            return None
        header_size, _, _, kind = struct.unpack_from(">IIII", frame)
        if kind not in _OP_TYPES or header_size < FIXED_HEADER + 16:
            return None
        return struct.unpack_from(">Q", frame, FIXED_HEADER)[0] >> 32


    def decode_row(
        payload: memoryview, columns: Iterable[ColumnDescriptor], *, null_byte: str = "keep"
    ) -> dict[str, Any]:
        offset, row = 0, {}
        for column in columns:
            try:
                value, consumed = decode_value(payload[offset:], column, null_byte=null_byte)
            except (CdcProtocolError, UnicodeDecodeError) as error:
                # UnicodeDecodeError is raised by the text branches of decode_value
                # and is not a CdcProtocolError, so catching only the latter let a
                # bare codec error escape without naming the column or offset -- the
                # two facts needed to tell a genuine encoding mismatch apart from a
                # payload that does not belong to this row at all. Re-raise both with
                # that context attached.
                raise CdcProtocolError(
                    f"failed to decode CDC column {column.name!r} at payload offset {offset}: {error}"
                ) from error
            if consumed <= 0 or offset + consumed > len(payload):
                raise CdcProtocolError(f"invalid width for CDC column {column.name}")
            row[column.name] = value
            offset += consumed
        if offset != len(payload):
            raise CdcProtocolError(f"CDC row has {len(payload) - offset} trailing bytes")
        return row


    def apply_null_byte(value: Any, mode: str) -> Any:
        # Docstring: Sanitize a decoded string that contains an embedded NUL (``\\x00``).
        #
        # ``mode`` selects the behaviour (shared by the CDC and snapshot decode paths):
        #
        # - ``"keep"`` -- return the value unchanged; a NUL passes straight through.
        # - ``"null"`` -- a string containing any NUL becomes ``None``. A NUL is genuine
        #   content here (the decoders already trim real padding), so it cannot be
        #   represented as a clean string; ``None`` says so honestly and is detectable
        #   downstream rather than silently altering the value.
        # - ``"empty"`` -- strip the NUL characters, preserving the rest of the string.
        #
        # Non-string values, and NUL-free strings, are returned unchanged regardless of mode.

        if mode == "keep" or not isinstance(value, str) or "\x00" not in value:
            return value
        if mode == "null":
            return None
        return value.replace("\x00", "")


    def decode_value(
        data: memoryview, column: ColumnDescriptor, *, null_byte: str = "keep"
    ) -> tuple[Any, int]:
        value, consumed = _decode_value_bytes(data, column)
        return apply_null_byte(value, null_byte), consumed


    def _decode_value_bytes(data: memoryview, column: ColumnDescriptor) -> tuple[Any, int]:
        kind = column.type_name.upper().split("(", 1)[0].strip()
        if kind in {"SMALLINT", "INT2"}:
            value = _unpack(">h", data)
            return (None if value == -(1 << 15) else value), 2
        if kind in {"INTEGER", "INT", "SERIAL"}:
            value = _unpack(">i", data)
            return (None if value == -(1 << 31) else value), 4
        if kind in {"BIGINT", "BIGSERIAL"}:
            value = _unpack(">q", data)
            return (None if value == -(1 << 63) else value), 8
        if kind == "DATE":
            value = _unpack(">i", data)
            if value == -(1 << 31):
                return None, 4
            # Informix day zero is 1899-12-31. The native conversion adds
            # 693594 to a zero-based Julian-day value; Python ordinals are one-based.
            return date(1, 1, 1) + timedelta(days=value + 693594), 4
        if kind in {"FLOAT", "DOUBLE", "DOUBLE PRECISION"}:
            _need(data, 8)
            if bytes(data[:8]) == b"\xff" * 8:
                return None, 8
            value = _unpack(">d", data)
            return value, 8
        if kind in {"REAL", "SMALLFLOAT"}:
            _need(data, 4)
            if bytes(data[:4]) == b"\xff" * 4:
                return None, 4
            value = _unpack(">f", data)
            return value, 4
        if kind in {"BOOLEAN", "BOOL"}:
            _need(data, 2)
            null_flag = data[0]
            marker = struct.unpack_from(">b", data, 1)[0]
            if null_flag == 1:
                return None, 2
            if null_flag != 0:
                raise CdcProtocolError(f"invalid boolean null flag {null_flag}")
            if marker not in {0, 1}:
                raise CdcProtocolError(f"invalid boolean marker {marker}")
            return bool(marker), 2
        if kind in {"CHAR", "NCHAR"}:
            _need(data, column.length)
            return bytes(data[: column.length]).decode(column.encoding).rstrip(" "), column.length
        if kind in {"VARCHAR", "NVARCHAR"}:
            _need(data, 1)
            length = int(data[0])
            if length == 1:
                _need(data, 2)
                if data[1] == 0:
                    return None, 2
            _need(data, length + 1)
            return bytes(data[1 : length + 1]).decode(column.encoding), length + 1
        if kind == "LVARCHAR":
            _need(data, 3)
            length = struct.unpack_from(">h", data)[0]
            if length < 0:
                raise CdcProtocolError(f"invalid LVARCHAR length {length}")
            _need(data, length + 2)
            if length == 1 and data[2] == 1:
                return None, 3
            if length == 1 and data[2] == 0:
                return "", 3
            return bytes(data[3 : length + 2]).decode(column.encoding), length + 2
        if kind in {"DECIMAL", "NUMERIC", "MONEY"}:
            if column.precision is None or column.scale is None:
                raise UnsupportedCdcType(f"{kind} requires precision and scale metadata")
            size = (column.precision + (column.scale & 1) + 3) // 2
            _need(data, size)
            return decode_packed_decimal(bytes(data[:size]), column.precision, column.scale), size
        if kind in {"INT8", "SERIAL8"}:
            _need(data, 10)
            sign = struct.unpack_from(">h", data)[0]
            if sign == 0:
                return None, 10
            if sign not in {-1, 1}:
                raise CdcProtocolError(f"invalid {kind} sign word {sign}")
            low = struct.unpack_from(">I", data, 2)[0]
            high = struct.unpack_from(">I", data, 6)[0]
            magnitude = (high << 32) | low
            if magnitude > 1 << 63 or (sign == 1 and magnitude == 1 << 63):
                raise CdcProtocolError(f"{kind} magnitude exceeds signed int64")
            return (-magnitude if sign == -1 else magnitude), 10
        if kind == "DATETIME":
            return _decode_datetime(data, column)
        if kind == "INTERVAL":
            return decode_interval(data, column.length)
        if kind in {"BYTE", "TEXT", "BLOB", "CLOB", "UDT", "ROW", "SET", "LIST"}:
            raise UnsupportedCdcType(f"{kind} is not supported by the IBM capture-column path")
        raise UnsupportedCdcType(f"unsupported CDC type {column.type_name}")


    def _unpack(fmt: str, data: memoryview):
        size = struct.calcsize(fmt)
        _need(data, size)
        return struct.unpack_from(fmt, data)[0]


    def decode_packed_decimal(data: bytes, precision: int, scale: int) -> Decimal | None:
        variable_scale = scale == 0xFF
        if not 1 <= precision <= 38 or not (variable_scale or 0 <= scale <= precision):
            raise UnsupportedCdcType(f"invalid DECIMAL({precision},{scale}) metadata")
        expected = (precision + (scale & 1) + 3) // 2
        if len(data) != expected:
            raise CdcProtocolError(f"packed decimal is {len(data)} bytes, expected {expected}")
        if data[:2] == b"\0\0":
            return None
        positive = bool(data[0] & 0x80)
        header = data[0] if positive else data[0] ^ 0x7F
        exponent = (header & 0x7F) - 64
        digits = list(data[1:])
        if any(digit > 99 for digit in digits):
            raise CdcProtocolError("packed decimal contains a base-100 digit above 99")
        if not positive:
            carrying = False
            for index in range(len(digits) - 1, -1, -1):
                digit = digits[index]
                if not carrying and digit == 0:
                    continue
                digits[index] = (100 if not carrying else 99) - digit
                carrying = True
        with localcontext() as context:
            context.prec = max(precision + 8, 46)
            value = sum(
                Decimal(digit) * (Decimal(100) ** (exponent - index - 1))
                for index, digit in enumerate(digits)
            )
            if not positive:
                value = -value
            if variable_scale:
                return value
            return value.quantize(Decimal(1).scaleb(-scale))


    def _decode_datetime(
        data: memoryview, column: ColumnDescriptor
    ) -> tuple[datetime | str | None, int]:
        qualifier = column.length
        start, end = (qualifier >> 8) & 0xF, qualifier & 0xF
        codes = (0, 2, 4, 6, 8, 10)
        if start not in codes or end not in {*codes, 11, 12, 13, 14, 15} or end < start:
            raise UnsupportedCdcType(f"unsupported DATETIME qualifier {start} TO {end}")
        selected = [code for code in codes if start <= code <= min(end, 10)]
        widths = {0: 4, 2: 2, 4: 2, 6: 2, 8: 2, 10: 2}
        fraction_digits = max(0, end - 10)
        digit_count = sum(widths[code] for code in selected) + fraction_digits
        size = 1 + (digit_count + 1) // 2
        _need(data, size)
        raw = bytes(data[:size])
        if raw[:2] == b"\0\0":
            return None, size
        if not raw[0] & 0x80:
            raise CdcProtocolError("DATETIME packed value must be non-negative")
        groups = raw[1:]
        if any(group > 99 for group in groups):
            raise CdcProtocolError("DATETIME contains a base-100 group above 99")
        exponent = (raw[0] & 0x7F) - 64
        whole_groups = sum(widths[code] for code in selected) // 2
        grid = whole_groups + (fraction_digits + 1) // 2
        # ``groups`` is a fixed-width, left-aligned mantissa -- most significant *non-zero*
        # base-100 group first, ``exponent`` giving that group's base-100 place -- exactly as
        # decode_packed_decimal reads a DECIMAL. Reconstruct the fixed [whole | fraction] grid
        # by shifting the mantissa back right over the leading zero groups normalization
        # stripped. ``exponent`` can be <= 0 for a sub-unit value (e.g. 00:00:00.00042 in a
        # HOUR TO FRACTION column, whose whole groups and first fraction group are all zero);
        # only ``exponent > whole_groups`` -- more integer groups than the qualifier admits --
        # is a true overflow.
        if exponent > whole_groups:
            raise CdcProtocolError(f"DATETIME exponent {exponent} exceeds its qualifier width")
        combined = [0] * (whole_groups - exponent) + list(groups)
        # A non-zero group shifted past the fraction's resolution would be a value finer than
        # the qualifier -- silent data loss rather than a decode we can trust.
        if any(combined[grid:]):
            raise CdcProtocolError(
                f"DATETIME value carries more precision than its {start} TO {end} qualifier"
            )
        digits = "".join(f"{group:02d}" for group in combined[:grid])[
            : whole_groups * 2 + fraction_digits
        ]
        values, position = {}, 0
        for code in selected:
            width = widths[code]
            values[code] = int(digits[position : position + width])
            position += width
        fraction = digits[position:]
        ranges = {
            0: (1, 9999),
            2: (1, 12),
            4: (1, 31),
            6: (0, 23),
            8: (0, 59),
            10: (0, 59),
        }
        for code, value in values.items():
            minimum, maximum = ranges[code]
            if not minimum <= value <= maximum:
                raise CdcProtocolError(f"invalid DATETIME field {code} value {value} in {digits}")
        if 2 in values and 4 in values:
            maximum_day = {
                1: 31,
                2: 29,
                3: 31,
                4: 30,
                5: 31,
                6: 30,
                7: 31,
                8: 31,
                9: 30,
                10: 31,
                11: 30,
                12: 31,
            }[values[2]]
            if values[4] > maximum_day:
                raise CdcProtocolError(f"invalid DATETIME calendar fields {digits}")
        if {0, 2, 4}.issubset(values):
            try:
                decoded = datetime(
                    values[0],
                    values[2],
                    values[4],
                    values.get(6, 0),
                    values.get(8, 0),
                    values.get(10, 0),
                    int((fraction + "000000")[:6] or 0),
                )
            except ValueError as exc:
                raise CdcProtocolError(f"invalid DATETIME calendar fields {digits}") from exc
            # Year 1 (e.g. the 0001-01-01 00:00:00 sentinel) sits adjacent to
            # ``datetime.min``. PySpark converts a TimestampType value with
            # ``datetime.astimezone()``, which subtracts the session UTC offset and
            # overflows below ``datetime.min`` for a naive year-1 value, failing the read.
            # Attaching UTC makes ``astimezone(UTC)`` a true no-op, so 0001-01-01T00:00:00Z
            # passes through into the DataFrame intact. Safe because Informix DATETIME
            # carries no timezone, so treating the wall clock as UTC preserves its value.
            if values[0] <= 1:
                decoded = decoded.replace(tzinfo=timezone.utc)
            return decoded, size
        if start == 6:
            rendered = ":".join(f"{values[code]:0{widths[code]}d}" for code in selected)
            if fraction:
                rendered += f".{fraction}"
            return rendered, size
        labels = {0: "YEAR", 2: "MONTH", 4: "DAY", 6: "HOUR", 8: "MINUTE", 10: "SECOND"}
        rendered = ":".join(f"{labels[code]}={values[code]:0{widths[code]}d}" for code in selected)
        if fraction:
            rendered += f":FRACTION({fraction_digits})={fraction}"
        return rendered, size


    # INTERVAL qualifier field codes: YEAR, MONTH | DAY, HOUR, MINUTE, SECOND, then
    # FRACTION(n) as 10 + n. The separator written before each field after the first.
    _INTERVAL_SEPARATORS = {2: "-", 6: " ", 8: ":", 10: ":"}
    _INTERVAL_FIELD_LIMITS = {2: 12, 6: 24, 8: 60, 10: 60}


    def interval_layout(qualifier: int) -> tuple[tuple[int, ...], int, int] | None:
        # Docstring: Split an INTERVAL qualifier into ``(fields, leading_digits, fraction)``.
        #
        # ``qualifier`` is the syscolumns.collength layout, which SQLI result descriptors
        # carry too: total digits in the high byte, then the start and end field codes in
        # the low byte's nibbles (``DAY(3) TO SECOND`` is 0x094a). ``FRACTION TO
        # FRACTION(n)`` starts at code 12 whatever n is, so its end code 10 + n can sit below
        # its start (0x01cb for n = 1); it has no fields, only the fraction. Returns None for
        # a qualifier no INTERVAL can have, such as one mixing YEAR-MONTH and DAY-TIME fields.

        total, start, end = (qualifier >> 8) & 0xFF, (qualifier >> 4) & 0xF, qualifier & 0xF
        if start == 12:
            return ((), 0, end - 10) if 11 <= end <= 15 and total == end - 10 else None
        if start in (0, 2):
            if end not in (0, 2) or end < start:
                return None
        elif start not in (4, 6, 8, 10) or end not in (4, 6, 8, 10, 11, 12, 13, 14, 15):
            return None
        if end < start:
            return None
        fields = tuple(range(start, min(end, 10) + 1, 2))
        fraction = end - 10 if end > 10 else 0
        leading = total - 2 * (len(fields) - 1) - fraction
        if not 1 <= leading <= 9:
            return None
        return fields, leading, fraction


    def decode_interval(data: memoryview, qualifier: int) -> tuple[str | None, int]:
        # Docstring: Decode a packed INTERVAL into Informix's literal text, e.g. ``-5 10:30:00.250``.
        #
        # An INTERVAL is stored as a signed packed DECIMAL whose digits are its fields run
        # together on a fixed grid: the decimal point always follows the SECOND position,
        # whatever the qualifier's last field, so ``HOUR TO MINUTE`` holds 10:30 as 103000 and
        # ``YEAR TO MONTH`` holds 1-02 as 10200000000 (measured on Informix 14.10). The text
        # gives the first field without padding, the rest two digits each, and the fraction
        # at its declared width, with ``-`` before a negative interval -- Informix's own
        # rendering, trimmed. ``FRACTION TO FRACTION(n)`` has no field before the point and
        # renders as ``.016`` or ``-.016``. Delta tables cannot store Spark's interval types,
        # so this text is what lands.

        layout = interval_layout(qualifier)
        if layout is None:
            raise UnsupportedCdcType(f"unsupported INTERVAL qualifier 0x{qualifier:04x}")
        fields, leading, fraction = layout
        total = (qualifier >> 8) & 0xFF
        size = (total + (fraction & 1) + 3) // 2
        _need(data, size)
        value = decode_packed_decimal(bytes(data[:size]), total, fraction)
        if value is None:
            return None, size
        negative = value < 0
        magnitude = -value if negative else value
        text = "-" if negative and magnitude else ""
        if not fields:
            if int(magnitude):
                raise CdcProtocolError(f"INTERVAL holds digits above its fraction: {value}")
        else:
            whole, below = divmod(int(magnitude), 10 ** (10 - fields[-1]))
            if below:
                raise CdcProtocolError(f"INTERVAL holds digits below its last field: {value}")
            parts = []
            for code in reversed(fields[1:]):
                whole, part = divmod(whole, 100)
                if part >= _INTERVAL_FIELD_LIMITS[code]:
                    raise CdcProtocolError(f"INTERVAL field {code} holds {part}")
                parts.append(f"{_INTERVAL_SEPARATORS[code]}{part:02d}")
            if whole >= 10**leading:
                raise CdcProtocolError(f"INTERVAL leading field {whole} exceeds {leading} digits")
            text += str(whole) + "".join(reversed(parts))
        if fraction:
            text += "." + str(int((magnitude - int(magnitude)).scaleb(fraction))).zfill(fraction)
        return text, size


    def _need(data: memoryview, size: int) -> None:
        if size < 0 or len(data) < size:
            raise CdcProtocolError(f"truncated CDC value: need {size}, have {len(data)}")


    def _require_header(header: memoryview, size: int, op: str) -> None:
        # IBM's record classes consume only the known prefix from ByteBuffer and
        # deliberately tolerate server-version-specific header extensions.
        if len(header) < size:
            raise CdcProtocolError(f"{op} header is {len(header)} bytes, expected at least {size}")


    __all__ = [
        "CdcFrameParser",
        "CdcProtocolError",
        "ColumnDescriptor",
        "OpenTransactionRecords",
        "UnsupportedCdcType",
        "apply_null_byte",
        "decode_frame",
        "decode_interval",
        "interval_layout",
        "metadata_column_names",
        "decode_packed_decimal",
        "decode_row",
        "decode_value",
        "validate_snapshot_arity",
    ]


    ########################################################
    # src/databricks/labs/community_connector/sources/informix/lakebase_state.py
    ########################################################

    _LOGGER = logging.getLogger(__name__)

    # Autoscaling bounds. 0.5 is the smallest compute unit the API accepts; the
    # ceiling exists so a runaway reader cannot scale the endpoint without limit.
    # Measured cost at the floor is well under the S3 request charges this replaces.
    _DEFAULT_MIN_CU = 0.5
    _DEFAULT_MAX_CU = 2.0
    # Idle seconds before the endpoint suspends to zero compute. Measured resume
    # cost from IDLE is ~3.3s to connect plus one ordinary query, so a short timeout
    # is affordable: a continuously streaming pipeline never reaches it, and a
    # pipeline that does was idle anyway.
    _DEFAULT_SUSPEND_SECONDS = 60
    _AUTO_PROJECT_PREFIX = "informix-state-"

    # A suspended endpoint must be allowed to wake. This bounds the *connect*, not a
    # steady-state query, and is generous relative to the ~3.3s measured resume.
    _CONNECT_TIMEOUT_SECONDS = 120
    # How long a slot-queue ticket stays authoritative without a heartbeat. A waiter
    # heartbeats every sweep (<= 2s), so this is many sweeps of slack -- enough that a
    # briefly-stalled live waiter is never mistaken for a crashed one -- yet far below the
    # 120s slot lease, so a truly dead waiter's ticket stops blocking the queue quickly.
    _DEFAULT_WAITER_TTL_SECONDS = 15.0
    # OAuth credentials last an hour; recycle pooled connections well before that so
    # no connection is ever handed out holding a nearly-expired token.
    _CREDENTIAL_REFRESH_SECONDS = 2700

    _DEFAULT_DATABASE = "databricks_postgres"
    # Point libpq's client-certificate lookup at a path that does not exist.
    #
    # Authentication here is by password or OAuth credential, never by client
    # certificate, but libpq still probes ``$HOME/.postgresql/postgresql.crt`` and
    # treats *any* error opening it as fatal -- including EACCES. The pipeline's reader
    # processes run with ``HOME=/root``, which they cannot traverse, so every connection
    # failed with ``could not open certificate file ... Permission denied``.
    #
    # A missing explicit path is skipped, which an empty string is not: an empty
    # ``sslcert`` falls back to the default location and fails again, and ``/dev/null``
    # is read and rejected ("no start line"). Verified against a live endpoint, where
    # this still negotiates TLSv1.3 -- it disables only client-certificate auth, which
    # is unused, and leaves ``sslmode=require`` in force.
    _NO_CLIENT_CERTIFICATE = {
        "sslcert": "/nonexistent/informix-state-no-client-cert.crt",
        "sslkey": "/nonexistent/informix-state-no-client-cert.key",
    }
    # The state role is fixed rather than configurable. It exists solely to own this
    # connector's state tables, so letting a connection name it would add a way to
    # misconfigure the pipeline without adding anything it could express: two
    # pipelines pointing at one endpoint must agree on the role that owns the tables.
    STATE_ROLE = "informix_state_user"
    _DEFAULT_BRANCH = "production"
    _DEFAULT_ENDPOINT = "primary"

    # Long-running provisioning calls return an operation envelope; poll until done.
    _OPERATION_POLL_SECONDS = 2.0
    _OPERATION_TIMEOUT_SECONDS = 900.0

    _API_TIMEOUT_SECONDS = 120.0
    _API_ATTEMPTS = 4
    _DEFAULT_PROVISION_TIMEOUT_SECONDS = 180.0

    # --- Snapshot-page staging over the Files REST API -------------------------------
    # The connector can stage snapshot page payloads through the Files API instead of the
    # UC Volume FUSE mount (see the connector's snapshot.staging.transport option), which
    # sidesteps the FUSE-mount disconnects that recur under sustained write frequency.
    # Reaching the Files API needs a bearer token, but the reader processes that stage
    # pages have no ambient identity -- only the driver, at module-load, does. So a
    # personal access token is minted from the driver-captured credential, carried to the
    # reader in _CAPTURED_WORKSPACE, and thereafter refreshed by the still-valid token
    # minting its own successor -- no ambient identity is needed after the first mint.
    # Each token is tagged with the pipeline id so a restart can revoke its predecessors.
    STAGING_TOKEN_COMMENT_PREFIX = "informix-snapshot-staging:"
    _DEFAULT_STAGING_TOKEN_LIFETIME_SECONDS = 86400
    # Refresh at half-life: a token minted with lifetime L is replaced after L/2, so a
    # missed or slow refresh still leaves L/2 of validity before anything can 401.
    _STAGING_TOKEN_REFRESH_FRACTION = 0.5
    _STAGING_TOKEN_MIN_LIFETIME_SECONDS = 600
    _FILES_API_TIMEOUT_SECONDS = 300.0
    _FILES_API_ATTEMPTS = 4


    class LakebaseStateError(RuntimeError):
        # Docstring: Raised when Lakebase-backed state cannot be provisioned or reached.
        pass


    class WorkspaceHttpError(LakebaseStateError):
        # Docstring: A workspace control-plane call returned a non-retriable HTTP status.
        #
        # Subclasses ``LakebaseStateError`` so existing ``except LakebaseStateError``
        # handlers are unaffected; it merely carries ``status_code`` so a caller can
        # branch on, for example, a 403 that means a feature is disabled.

        def __init__(self, message: str, status_code: int) -> None:
            super().__init__(message)
            self.status_code = status_code


    def project_id_for_connection(identity: str, prefix: str = "informix-state") -> str:
        # Docstring: Derive a stable, DNS-compliant project id from a connection identity.
        #
        # The id must be reproducible: every worker in every update has to resolve the
        # same project without coordinating, and the project is the unit that ties
        # state to one Informix connection. Hashing the identity also avoids leaking a
        # hostname into a globally visible resource name.

        digest = hashlib.sha256(identity.encode("utf-8")).hexdigest()[:16]
        return f"{prefix}-{digest}"


    class _WorkspaceApi:
        # Docstring: Minimal REST client for the workspace control plane.
        #
        # Deliberately stdlib-only. This module is imported inside Spark workers where
        # adding a dependency is a deployment problem, and the surface needed here is
        # four verbs against JSON endpoints.

        def __init__(self, host: str, token: str) -> None:
            self._host = host.rstrip("/")
            self._token = token

        def request(
            self,
            method: str,
            path: str,
            body: dict[str, Any] | None = None,
            *,
            tolerate_missing: bool = False,
            deadline: float | None = None,
        ) -> dict[str, Any] | None:
            url = f"{self._host}{path}"
            payload = json.dumps(body).encode("utf-8") if body is not None else None
            last_error: Exception | None = None
            for attempt in range(_API_ATTEMPTS):
                remaining = None if deadline is None else deadline - time.monotonic()
                if remaining is not None and remaining <= 0:
                    raise LakebaseStateError(f"Lakebase provisioning timed out during {method} {path}")
                request = urllib.request.Request(
                    url,
                    data=payload,
                    method=method,
                    headers={
                        "Authorization": f"Bearer {self._token}",
                        "Content-Type": "application/json",
                    },
                )
                try:
                    timeout = (
                        _API_TIMEOUT_SECONDS
                        if remaining is None
                        else min(_API_TIMEOUT_SECONDS, max(0.1, remaining))
                    )
                    with urllib.request.urlopen(request, timeout=timeout) as response:
                        raw = response.read()
                    return json.loads(raw) if raw else {}
                except urllib.error.HTTPError as error:
                    if error.code == 404 and tolerate_missing:
                        return None
                    # 409 means someone else won a concurrent create; the caller
                    # treats that as success, so do not burn retries on it.
                    if error.code == 409:
                        raise LakebaseStateError(f"conflict on {method} {path}") from error
                    if error.code < 500 and error.code != 429:
                        detail = error.read().decode("utf-8", "replace")[:400]
                        raise WorkspaceHttpError(
                            f"{method} {path} failed with HTTP {error.code}: {detail}",
                            error.code,
                        ) from error
                    last_error = error
                except (urllib.error.URLError, TimeoutError, json.JSONDecodeError) as error:
                    last_error = error
                if attempt + 1 < _API_ATTEMPTS:
                    delay = min(1.5 * (2**attempt), 8.0)
                    if deadline is not None:
                        delay = min(delay, max(0.0, deadline - time.monotonic()))
                    if delay:
                        time.sleep(delay)
            raise LakebaseStateError(f"{method} {path} failed after {_API_ATTEMPTS} attempts") from (
                last_error
            )

        def await_operation(
            self, envelope: dict[str, Any] | None, *, deadline: float | None = None
        ) -> dict[str, Any]:
            # Docstring: Resolve a long-running-operation envelope to its final response.
            #
            # Provisioning calls may return either a finished resource or an operation
            # that has to be polled; both shapes arrive on the same code path.

            if not envelope:
                return {}
            if "name" not in envelope or "/operations/" not in str(envelope.get("name", "")):
                return envelope
            operation_deadline = time.monotonic() + _OPERATION_TIMEOUT_SECONDS
            if deadline is not None:
                operation_deadline = min(operation_deadline, deadline)
            operation = envelope
            while not operation.get("done"):
                if time.monotonic() > operation_deadline:
                    raise LakebaseStateError(
                        f"Lakebase provisioning timed out waiting for operation {operation.get('name')}"
                    )
                time.sleep(
                    min(_OPERATION_POLL_SECONDS, max(0.0, operation_deadline - time.monotonic()))
                )
                operation = (
                    self.request(
                        "GET", f"/api/2.0/postgres/{operation['name']}", deadline=operation_deadline
                    )
                    or {}
                )
            if "error" in operation:
                raise LakebaseStateError(f"operation failed: {operation['error']}")
            return operation.get("response") or {}


    # Workspace credentials captured on the driver, for use where none exist.
    #
    # Measured in a serverless pipeline (2026-08-08): ambient workspace identity is
    # resolvable *only* while the pipeline module executes on the driver, where
    # ``WorkspaceClient()`` returns ``auth_type=runtime``. Every process the reader
    # actually runs in -- the Python streaming source runner and Spark's Python
    # workers -- has no credential material at all: no auth environment variables, no
    # ``~/.databrickscfg``, no active Spark session, and ``dbutils`` itself fails to
    # initialise. ``HOME=/root`` there is unreadable, so the SDK's config-file loader
    # raises ``PermissionError`` before it even reaches auth resolution; repointing
    # ``HOME`` merely exchanges that for "cannot configure default credentials".
    #
    # Provisioning cannot simply move to the driver: at module-execution time no
    # connection and no options exist yet, so the ``lakebase.*`` overrides it needs
    # are unreachable. Options and ambient auth are available in disjoint processes.
    # Capturing the credential on the driver and carrying it to where the options
    # live is what bridges them. Held in a dict so the merged single-file deployment,
    # which turns module globals into function locals, can still mutate it.
    _CAPTURED_WORKSPACE: dict[str, str] = {}


    def capture_workspace_credentials() -> dict[str, str]:
        # Docstring: Record the driver's ambient workspace credentials for later use.
        #
        # Call once while the pipeline module executes on the driver. Failure is not
        # fatal here: an explicitly configured host/token still works, and raising
        # would break registration for deployments that never touch Lakebase.

        if not os.environ.get("DATABRICKS_RUNTIME_VERSION"):
            # Only a Databricks runtime has an ambient identity worth capturing. This
            # keeps unit tests -- which import and register the module -- from trying
            # to authenticate at all.
            return _CAPTURED_WORKSPACE
        try:
            from databricks.sdk import WorkspaceClient  # noqa: PLC0415

            client = WorkspaceClient()
            header = client.config.authenticate() or {}
            token = str(header.get("Authorization", "")).split(" ", 1)[-1]
            host = str(client.config.host or "")
            if host and token:
                _CAPTURED_WORKSPACE["host"] = host
                _CAPTURED_WORKSPACE["token"] = token
                _LOGGER.info("Captured workspace credentials for Lakebase provisioning")
        except Exception:  # pragma: no cover - depends on runtime
            # Debug, not warning: a package import outside a Databricks runtime takes
            # this path routinely and legitimately.
            _LOGGER.debug("No ambient workspace credentials on the driver", exc_info=True)
        return _CAPTURED_WORKSPACE


    def _workspace_credentials(options: dict[str, str]) -> tuple[str, str]:
        # Docstring: Resolve the workspace host and bearer token for control-plane calls.
        #
        # Prefers explicit options, then the credential captured on the driver, then
        # the ambient identity. The captured value is what makes this work inside a
        # pipeline at all, because the calling process has no identity of its own.

        host = (
            options.get("lakebase.workspace.host")
            or _CAPTURED_WORKSPACE.get("host")
            or os.environ.get("DATABRICKS_HOST")
            or ""
        ).strip()
        token = (
            options.get("lakebase.workspace.token")
            or _CAPTURED_WORKSPACE.get("token")
            or os.environ.get("DATABRICKS_TOKEN")
            or ""
        ).strip()
        if host and not host.startswith("http"):
            host = f"https://{host}"
        if not host or not token:
            # The SDK resolves notebook/job/serverless credentials that are not
            # exposed as environment variables. Imported lazily so the module keeps
            # working where the SDK is absent but explicit options are supplied.
            try:
                from databricks.sdk import WorkspaceClient  # noqa: PLC0415
            except ImportError as error:  # pragma: no cover - depends on runtime
                raise LakebaseStateError(
                    "Lakebase state needs a workspace host and token; set "
                    "lakebase.workspace.host/lakebase.workspace.token or install databricks-sdk"
                ) from error
            client = WorkspaceClient()
            host = host or client.config.host
            token = token or client.config.authenticate()["Authorization"].split(" ", 1)[1]
        return host, token


    def ensure_project(
        api: _WorkspaceApi,
        project_id: str,
        *,
        min_cu: float = _DEFAULT_MIN_CU,
        max_cu: float = _DEFAULT_MAX_CU,
        suspend_seconds: int = _DEFAULT_SUSPEND_SECONDS,
        deadline: float | None = None,
    ) -> dict[str, Any]:
        # Docstring: Create the project if absent and return the endpoint's connection facts.
        #
        # ``default_endpoint_settings`` is supplied at creation because that is the
        # only point at which ``suspend_timeout_duration`` reaches the auto-created
        # ``primary`` endpoint (see module docstring). An existing project is left
        # exactly as it is: adjusting a live endpoint's capacity is an operator
        # decision, not something a reader should do behind the operator's back.

        deadline_kwargs = {"deadline": deadline} if deadline is not None else {}
        existing = api.request(
            "GET",
            f"/api/2.0/postgres/projects/{project_id}",
            tolerate_missing=True,
            **deadline_kwargs,
        )
        if existing is not None and existing.get("delete_time"):
            # Lakebase retains a deleted project as a tombstone until its purge
            # time. GET still returns that tombstone, but it has no branch or
            # endpoint and its id cannot be recreated. Purge it explicitly so the
            # connector can safely recreate its deterministic project id.
            purged = api.request(
                "DELETE",
                f"/api/2.0/postgres/projects/{project_id}?purge=true",
                **deadline_kwargs,
            )
            if deadline is None:
                api.await_operation(purged)
            else:
                api.await_operation(purged, deadline=deadline)
            existing = api.request(
                "GET",
                f"/api/2.0/postgres/projects/{project_id}",
                tolerate_missing=True,
                **deadline_kwargs,
            )
            if existing is not None:
                raise LakebaseStateError(f"purged Lakebase project {project_id} is still visible")
            _LOGGER.info("Purged deleted Lakebase project tombstone %s", project_id)
        if existing is None:
            body = {
                "spec": {
                    "default_endpoint_settings": {
                        "autoscaling_limit_min_cu": min_cu,
                        "autoscaling_limit_max_cu": max_cu,
                        "suspend_timeout_duration": f"{int(suspend_seconds)}s",
                    },
                    # Password (SCRAM) logins are refused unless this is on, and it is
                    # off by default. Set here because creation is also the only point
                    # the endpoint settings above take effect, so one call does both.
                    "enable_pg_native_login": True,
                }
            }
            try:
                created = api.request(
                    "POST",
                    f"/api/2.0/postgres/projects?project_id={project_id}",
                    body,
                    **deadline_kwargs,
                )
                if deadline is None:
                    api.await_operation(created)
                else:
                    api.await_operation(created, deadline=deadline)
                _LOGGER.info(
                    "Created Lakebase project %s (%.1f-%.1f CU, suspend %ss)",
                    project_id,
                    min_cu,
                    max_cu,
                    suspend_seconds,
                )
            except LakebaseStateError:
                # A concurrent worker may have created it between our GET and POST.
                # Re-reading is the check that matters; only a still-absent project
                # is a real failure.
                if (
                    api.request(
                        "GET",
                        f"/api/2.0/postgres/projects/{project_id}",
                        tolerate_missing=True,
                        **deadline_kwargs,
                    )
                    is None
                ):
                    raise
        return _endpoint_facts(api, project_id, deadline=deadline)


    def _endpoint_facts(
        api: _WorkspaceApi, project_id: str, *, deadline: float | None = None
    ) -> dict[str, Any]:
        # Docstring: Read the read-write endpoint's host and resource name.
        #
        # Waits for the endpoint to exist because project creation provisions it
        # asynchronously; an IDLE endpoint is ready to use, since connecting is what
        # wakes it.

        path = (
            f"/api/2.0/postgres/projects/{project_id}"
            f"/branches/{_DEFAULT_BRANCH}/endpoints/{_DEFAULT_ENDPOINT}"
        )
        endpoint_deadline = time.monotonic() + _OPERATION_TIMEOUT_SECONDS
        if deadline is not None:
            endpoint_deadline = min(endpoint_deadline, deadline)
        while True:
            request_kwargs = {"deadline": endpoint_deadline} if deadline is not None else {}
            endpoint = api.request("GET", path, tolerate_missing=True, **request_kwargs)
            status = (endpoint or {}).get("status") or {}
            host = (status.get("hosts") or {}).get("host")
            if host:
                return {
                    "endpoint": (
                        f"projects/{project_id}/branches/{_DEFAULT_BRANCH}"
                        f"/endpoints/{_DEFAULT_ENDPOINT}"
                    ),
                    "host": host,
                    "state": status.get("current_state"),
                    "min_cu": status.get("autoscaling_limit_min_cu"),
                    "max_cu": status.get("autoscaling_limit_max_cu"),
                    "suspend": status.get("suspend_timeout_duration"),
                }
            if time.monotonic() > endpoint_deadline:
                raise LakebaseStateError(
                    f"Lakebase provisioning timed out waiting for endpoint for project {project_id}"
                )
            time.sleep(min(_OPERATION_POLL_SECONDS, max(0.0, endpoint_deadline - time.monotonic())))


    def generate_credential(api: _WorkspaceApi, endpoint: str) -> str:
        # Docstring: Mint a short-lived Postgres OAuth token for ``endpoint``.
        #
        # Sends ``endpoint`` alone: the documented ``claims`` array is rejected by this
        # workspace's API (see module docstring), and the caller's own identity already
        # scopes the credential.

        response = api.request("POST", "/api/2.0/postgres/credentials", {"endpoint": endpoint})
        token = (response or {}).get("token")
        if not token:
            raise LakebaseStateError(f"no Postgres credential returned for {endpoint}")
        return token


    class StagingTokenUnavailable(RuntimeError):
        # Docstring: Personal access token creation is disabled or forbidden for this identity.
        #
        # Raised so the connector can fall back to the FUSE staging transport instead
        # of failing the flow: the Files-API transport cannot authenticate without a
        # token, and many workspaces disable PAT creation by policy.
        pass


    def mint_staging_token(
        api: _WorkspaceApi, pipeline_id: str, lifetime_seconds: int
    ) -> tuple[str, str]:
        # Docstring: Mint a personal access token for Files-API staging, tagged per pipeline.
        #
        # Returns ``(token_value, token_id)``. Raises :class:`StagingTokenUnavailable`
        # when the workspace forbids token creation (HTTP 403) or rejects it as
        # unsupported (HTTP 400), so the caller can fall back to FUSE rather than fail.

        comment = f"{STAGING_TOKEN_COMMENT_PREFIX}{pipeline_id}"
        try:
            response = (
                api.request(
                    "POST",
                    "/api/2.0/token/create",
                    {"comment": comment, "lifetime_seconds": int(lifetime_seconds)},
                )
                or {}
            )
        except WorkspaceHttpError as error:
            if error.status_code in (400, 403):
                raise StagingTokenUnavailable(
                    "workspace forbids personal access token creation; snapshot staging "
                    "cannot use the Files API transport"
                ) from error
            raise
        token_value = str(response.get("token_value") or "")
        token_id = str((response.get("token_info") or {}).get("token_id") or "")
        if not token_value:
            raise StagingTokenUnavailable("token creation returned no token value")
        return token_value, token_id


    def revoke_stale_staging_tokens(api: _WorkspaceApi, pipeline_id: str, keep_token_id: str) -> None:
        # Docstring: Delete this pipeline's previously-minted staging tokens, keeping the current one.
        #
        # Best-effort: listing or deleting may fail (e.g. the identity cannot manage
        # tokens it did not create), and an orphaned token expires on its own, so a
        # failure here is logged and swallowed rather than blocking startup.

        comment = f"{STAGING_TOKEN_COMMENT_PREFIX}{pipeline_id}"
        try:
            listing = api.request("GET", "/api/2.0/token/list") or {}
        except LakebaseStateError:
            _LOGGER.debug("Could not list personal access tokens for staging cleanup", exc_info=True)
            return
        for info in listing.get("token_infos") or []:
            token_id = str(info.get("token_id") or "")
            if info.get("comment") == comment and token_id and token_id != keep_token_id:
                try:
                    api.request("POST", "/api/2.0/token/delete", {"token_id": token_id})
                except LakebaseStateError:
                    _LOGGER.debug("Could not revoke stale staging token %s", token_id, exc_info=True)


    def store_staging_secret(api: _WorkspaceApi, scope: str, key: str, value: str) -> None:
        # Docstring: Persist the current staging token as a workspace secret (best-effort).
        #
        # The secret is a durable record for rotation/audit and cross-restart recovery;
        # it is *not* the reader's bootstrap source (reading a secret would itself need a
        # token). Staging always uses the in-process token carried in _CAPTURED_WORKSPACE,
        # so a failure to write the secret does not stop staging.

        try:
            api.request("POST", "/api/2.0/secrets/scopes/create", {"scope": scope})
        except WorkspaceHttpError as error:
            # 400 RESOURCE_ALREADY_EXISTS is the normal steady-state; anything else is
            # non-fatal here because the in-process token still works.
            if error.status_code not in (400, 409):
                _LOGGER.debug("Could not create secret scope %s", scope, exc_info=True)
        except LakebaseStateError:
            _LOGGER.debug("Could not create secret scope %s", scope, exc_info=True)
        try:
            api.request(
                "POST",
                "/api/2.0/secrets/put",
                {"scope": scope, "key": key, "string_value": value},
            )
        except LakebaseStateError:
            _LOGGER.debug("Could not store staging-token secret", exc_info=True)


    class StagingCredentialProvider:
        # Docstring: Supplies a Files-API bearer token, refreshing it before it can expire.
        #
        # The first ``bearer()`` mints a token using ``bootstrap_token`` -- whatever
        # credential the reader could carry from the driver (the captured runtime
        # credential). Every later refresh, at half-life, uses the *current minted
        # token* to mint its successor, so no ambient identity is needed after startup
        # (the reader process has none). Each mint also refreshes the durable secret and
        # revokes this pipeline's older tokens. Refresh is lazy -- checked on each
        # ``bearer()`` call -- so there is no background thread to manage; page writes
        # call ``bearer()`` often enough to refresh well within the half-life.
        #
        # A first-mint :class:`StagingTokenUnavailable` propagates so the caller falls
        # back to FUSE; a later *refresh* failure keeps the still-valid current token
        # rather than dropping a working credential.

        def __init__(
            self,
            host: str,
            bootstrap_token: str,
            pipeline_id: str,
            *,
            lifetime_seconds: int = _DEFAULT_STAGING_TOKEN_LIFETIME_SECONDS,
            secret_scope: str | None = None,
            secret_key: str | None = None,
            clock: Any = time.monotonic,
        ) -> None:
            self._host = host.rstrip("/")
            self._bootstrap_token = bootstrap_token
            self._pipeline_id = pipeline_id
            self._lifetime_seconds = max(_STAGING_TOKEN_MIN_LIFETIME_SECONDS, int(lifetime_seconds))
            self._refresh_after = self._lifetime_seconds * _STAGING_TOKEN_REFRESH_FRACTION
            self._secret_scope = secret_scope
            self._secret_key = secret_key
            self._clock = clock
            self._lock = threading.Lock()
            self._token: str | None = None
            self._token_id = ""
            self._minted_at = 0.0

        def bearer(self) -> str:
            with self._lock:
                now = self._clock()
                if self._token is None:
                    # First mint uses the carried bootstrap credential; a failure here is
                    # fatal for REST and surfaces as StagingTokenUnavailable to the caller.
                    self._mint(self._bootstrap_token)
                elif now - self._minted_at >= self._refresh_after:
                    try:
                        self._mint(self._token)
                    except Exception:  # noqa: BLE001 - keep the still-valid token on refresh failure
                        _LOGGER.warning(
                            "Snapshot-staging token refresh failed; reusing the current token",
                            exc_info=True,
                        )
                return self._token or ""

        def _mint(self, minting_token: str) -> None:
            token, token_id = mint_staging_token(
                _WorkspaceApi(self._host, minting_token), self._pipeline_id, self._lifetime_seconds
            )
            self._token = token
            self._token_id = token_id
            self._minted_at = self._clock()
            # Durability/rotation with the new token: store the secret and revoke the
            # tokens this pipeline minted before. Both are best-effort inside their helpers.
            new_api = _WorkspaceApi(self._host, token)
            if self._secret_scope and self._secret_key:
                store_staging_secret(new_api, self._secret_scope, self._secret_key, token)
            revoke_stale_staging_tokens(new_api, self._pipeline_id, token_id)


    class WorkspaceFilesApi:
        # Docstring: Read/write UC Volume files over the Files REST API instead of the FUSE mount.
        #
        # Only the verbs snapshot staging needs, stdlib-only for the same reason as
        # :class:`_WorkspaceApi`. The bearer token is fetched from the credential
        # provider on every attempt, so a token refreshed between attempts is picked up.

        def __init__(self, host: str, credential: StagingCredentialProvider) -> None:
            self._host = host.rstrip("/")
            self._credential = credential

        def put(self, volume_path: str, data: bytes) -> None:
            # Docstring: Upload ``data`` to ``volume_path`` (a /Volumes/... path), overwriting.

            self._request("PUT", volume_path, data=data, overwrite=True)

        def get(self, volume_path: str) -> bytes:
            # Docstring: Download ``volume_path``; raises on any non-200.

            return self._request("GET", volume_path) or b""

        def get_range(self, volume_path: str, start: int, end: int) -> bytes:
            # Docstring: Download the half-open byte range ``[start, end)`` of ``volume_path``.
            #
            # Issues a ranged GET (``Range: bytes=start-end-1``, inclusive per RFC 9110),
            # which the Files API answers with ``206 Partial Content``. Lets a reader pull
            # one split of a large file straight from object storage without materializing
            # the whole file (the serverless FUSE mount caches the whole file on first
            # access, so it is unsuitable for large files). ``end <= start`` yields ``b""``.

            if end <= start:
                return b""
            return self._request("GET", volume_path, byte_range=(start, end - 1)) or b""

        def _request(
            self,
            method: str,
            volume_path: str,
            *,
            data: bytes | None = None,
            overwrite: bool = False,
            byte_range: tuple[int, int] | None = None,
        ) -> bytes | None:
            quoted = urllib.parse.quote(volume_path, safe="/")
            url = f"{self._host}/api/2.0/fs/files{quoted}"
            if overwrite:
                url += "?overwrite=true"
            last_error: Exception | None = None
            for attempt in range(_FILES_API_ATTEMPTS):
                headers = {"Authorization": f"Bearer {self._credential.bearer()}"}
                if byte_range is not None:
                    # Inclusive, zero-based per RFC 9110; the Files API answers 206.
                    headers["Range"] = f"bytes={byte_range[0]}-{byte_range[1]}"
                if data is not None:
                    headers["Content-Type"] = "application/octet-stream"
                request = urllib.request.Request(url, data=data, method=method, headers=headers)
                try:
                    with urllib.request.urlopen(
                        request, timeout=_FILES_API_TIMEOUT_SECONDS
                    ) as response:
                        return response.read()
                except urllib.error.HTTPError as error:
                    if error.code < 500 and error.code != 429:
                        detail = error.read().decode("utf-8", "replace")[:400]
                        raise WorkspaceHttpError(
                            f"{method} files {volume_path} failed with HTTP {error.code}: {detail}",
                            error.code,
                        ) from error
                    last_error = error
                except (urllib.error.URLError, TimeoutError, http.client.IncompleteRead) as error:
                    # IncompleteRead: the server sent a valid response (for a ranged GET,
                    # a 206 with the full Content-Length) but the body transfer was cut
                    # short mid-stream. It is not a URLError/HTTPError, so without this it
                    # would escape the retry loop and kill the read. The request is
                    # deterministic and idempotent -- a ranged GET returns the same bytes
                    # every time -- so re-issuing it recovers the truncated transfer.
                    last_error = error
                if attempt + 1 < _FILES_API_ATTEMPTS:
                    time.sleep(min(1.5 * (2**attempt), 8.0))
            raise LakebaseStateError(
                f"{method} files {volume_path} failed after {_FILES_API_ATTEMPTS} attempts"
            ) from last_error


    def _quoted_identifier(connection: Any, name: str) -> str:
        # Docstring: Return ``name`` safely quoted for use as a Postgres identifier.
        #
        # A role name arrives from a connection option and lands in DDL, where it
        # cannot be a bind parameter. ``quote_ident`` is the server's own quoting, so
        # the escaping matches exactly what the server will parse.

        with connection.cursor() as cursor:
            cursor.execute("SELECT quote_ident(%s)", (name,))
            row = cursor.fetchone()
        if not row or not row[0]:
            raise LakebaseStateError(f"could not quote Lakebase role name {name!r}")
        return str(row[0])


    def ensure_login_role(admin_connection: Any, database: str, user: str, password: str) -> str:
        # Docstring: Create the password login role, or reset its password if it exists.
        #
        # Runs as the OAuth-authenticated workspace identity, which is the only caller
        # able to do this. Returns ``"created"`` or ``"reset"`` to say which happened.
        #
        # Reset rather than drop-and-recreate, deliberately. Once the role owns the
        # state tables -- which it does from its first run onwards -- ``DROP ROLE``
        # fails with ``DependentObjectsStillExist``, and the forced route
        # (``REASSIGN OWNED``/``DROP OWNED``) fails with ``InsufficientPrivilege``
        # because this identity holds CREATEROLE rather than superuser. Dropping would
        # also be the wrong outcome: the role owns ``conn_slots``, ``backlog_hints``
        # and ``state_records``, so removing it would discard the shared CDC state and
        # force every table to resnapshot. ``ALTER ROLE ... PASSWORD`` achieves the
        # same end -- the previous password stops working immediately -- while leaving
        # the data and its ownership untouched (all verified against a live endpoint).

        identifier = _quoted_identifier(admin_connection, user)
        database_identifier = _quoted_identifier(admin_connection, database)
        with admin_connection.cursor() as cursor:
            # The Python lock in LakebaseState.provision() is process-local, while a
            # Lakeflow pipeline starts one Python worker per flow. Serialize the
            # cluster-wide role tuple inside Postgres itself before inspecting or
            # changing it. This lock needs no connector schema and is released by
            # the commit/rollback below, so it is safe during first provisioning.
            cursor.execute(
                "SELECT pg_advisory_xact_lock(hashtextextended(%s, 0))",
                (f"lakeflow-informix-login-role:{user}",),
            )
            cursor.execute("SELECT 1 FROM pg_roles WHERE rolname = %s", (user,))
            exists = cursor.fetchone() is not None
            # LOGIN is stated explicitly in both branches: a pre-existing role may
            # have been created without it, and a role that cannot log in would fail
            # validation forever with an error indistinguishable from a bad password.
            verb = "ALTER" if exists else "CREATE"
            try:
                cursor.execute(f"{verb} ROLE {identifier} WITH LOGIN PASSWORD %s", (password,))
            except Exception as error:
                sqlstate = getattr(error, "sqlstate", None) or getattr(error, "pgcode", None)
                constraint = getattr(getattr(error, "diag", None), "constraint_name", None)
                if exists or sqlstate != "23505" or constraint != "pg_authid_rolname_index":
                    raise
                # A caller not using this advisory-lock protocol created the global
                # role after our pg_roles read.
                # PostgreSQL resolves the unique-index conflict only after the
                # winning CREATE commits, and every worker has the same configured
                # password. The failed CREATE aborts this transaction; rolling back
                # is sufficient. Issuing ALTER here would make all losing workers
                # update pg_authid concurrently and can fail with "tuple concurrently
                # updated".
                admin_connection.rollback()
                exists = True
        with admin_connection.cursor() as cursor:
            # Idempotent, and required for the role to create and own the schema.
            cursor.execute(f"GRANT ALL ON SCHEMA public TO {identifier}")
            cursor.execute(f"GRANT CREATE ON DATABASE {database_identifier} TO {identifier}")
        admin_connection.commit()
        return "reset" if exists else "created"


    # Schema for every piece of state that moved off the Volume. Written with
    # IF NOT EXISTS so concurrent provisioners converge instead of racing.
    #
    # ``conn_slots`` rows are pre-seeded per namespace, so acquisition is an UPDATE
    # of a free row rather than an INSERT. That keeps the table a fixed size and
    # makes capacity a property of how many rows exist, which cannot be exceeded by
    # any interleaving.
    _SCHEMA_STATEMENTS = (
        """
        CREATE TABLE IF NOT EXISTS conn_slots (
            namespace   text        NOT NULL,
            slot_id     integer     NOT NULL,
            owner       text,
            epoch       bigint      NOT NULL DEFAULT 0,
            scope       text,
            renewed_at  timestamptz,
            PRIMARY KEY (namespace, slot_id)
        )
        """,
        # Partial index: waiters only ever look for free or expired rows.
        """
        CREATE INDEX IF NOT EXISTS conn_slots_free_idx
            ON conn_slots (namespace, slot_id) WHERE owner IS NULL
        """,
        # Fair waiter queue: one row per reader currently blocked on a slot, carrying
        # its eligible band [floor, ceiling). ``ticket_id`` is a global monotonic
        # sequence, so a smaller ticket enqueued earlier -- acquisition consults it to
        # rank live waiters for each slot (see _ACQUIRE_SLOT). ``waiter_class`` tags each
        # ticket with its requester class so acquisition can rotate service across classes
        # rather than serve strictly by arrival; it defaults to 0 (the consumer class) so an
        # un-tagged ticket behaves as before.
        """
        CREATE TABLE IF NOT EXISTS slot_waiters (
            namespace    text        NOT NULL,
            ticket_id    bigserial   NOT NULL,
            owner        text        NOT NULL,
            floor        integer     NOT NULL,
            ceiling      integer     NOT NULL,
            waiter_class smallint    NOT NULL DEFAULT 0,
            heartbeat_at timestamptz NOT NULL DEFAULT now(),
            PRIMARY KEY (namespace, ticket_id)
        )
        """,
        # Add the class column in place for a slot_waiters table created by an older
        # deployment, so a mixed-version rollout is safe: tickets written before the
        # upgrade default to class 0. Guarded by an existence check rather than a bare
        # ``ALTER TABLE ... ADD COLUMN IF NOT EXISTS``: that form still takes an
        # ACCESS EXCLUSIVE lock on slot_waiters *every* time ensure_schema runs (even when
        # the column already exists), which deadlocks against the concurrent acquire_slot
        # transactions that read slot_waiters and write conn_slots/slot_rr_cursor. The DO
        # block only issues the ALTER (and takes the lock) on the one run that actually
        # migrates; once the column exists it is a lock-free catalog read.
        """
        DO $$
        BEGIN
            IF NOT EXISTS (
                SELECT 1 FROM information_schema.columns
                WHERE table_schema = current_schema()
                  AND table_name = 'slot_waiters'
                  AND column_name = 'waiter_class'
            ) THEN
                ALTER TABLE slot_waiters ADD COLUMN waiter_class smallint NOT NULL DEFAULT 0;
            END IF;
        END $$
        """,
        # Ordering scans walk a namespace's tickets oldest-first; the reaper filters by age.
        """
        CREATE INDEX IF NOT EXISTS slot_waiters_order_idx
            ON slot_waiters (namespace, ticket_id)
        """,
        # Round-robin rotation cursor: the requester class served most recently in a namespace.
        # The round-robin acquire reads it to rotate service to the next class; the winner
        # stamps its own class here. One row per namespace; -1 (the read-time default) means
        # nothing served yet, so the rotation begins at class 0.
        """
        CREATE TABLE IF NOT EXISTS slot_rr_cursor (
            namespace  text     NOT NULL,
            last_class smallint NOT NULL,
            PRIMARY KEY (namespace)
        )
        """,
        # reserved_deletes held a delete-channel slot reservation the connector no longer
        # has. Older connector versions sharing a namespace still write it, so it stays;
        # this one always writes 0.
        """
        CREATE TABLE IF NOT EXISTS conn_limits (
            namespace        text        PRIMARY KEY,
            max_connections  integer     NOT NULL,
            reserved_deletes integer     NOT NULL DEFAULT 0,
            version          integer     NOT NULL,
            updated_at       timestamptz NOT NULL DEFAULT now()
        )
        """,
        # One row per table, last writer wins under GREATEST. Replaces the
        # hints/gen-<bucket>/lsn-<20 digits> directory tree, its quantised bucket
        # walk-back, and its reaper: a monotonic upsert needs none of them.
        """
        CREATE TABLE IF NOT EXISTS backlog_hints (
            namespace   text        NOT NULL,
            table_name  text        NOT NULL,
            lsn         bigint      NOT NULL,
            updated_at  timestamptz NOT NULL DEFAULT now(),
            PRIMARY KEY (namespace, table_name)
        )
        """,
        # Write-once immutable records (schema nodes, initialization, schemas,
        # trigger scopes, snapshot metadata). INSERT ... ON CONFLICT DO NOTHING is
        # the head election that _publish_candidate_into_exclusive_head emulated
        # with a candidate file plus an exclusive rename.
        """
        CREATE TABLE IF NOT EXISTS state_records (
            namespace   text        NOT NULL,
            record_key  text        NOT NULL,
            record      jsonb       NOT NULL,
            record_type text        NOT NULL DEFAULT 'generic',
            created_at  timestamptz NOT NULL DEFAULT now(),
            PRIMARY KEY (namespace, record_key)
        )
        """,
        # Exact state reads use the primary key. GC and activity maintenance filter
        # by record type, so keep those scans inside one namespace and record class.
        """
        CREATE INDEX IF NOT EXISTS state_records_type_idx
            ON state_records (namespace, record_type)
        """,
        # Daily GC selects stale table-activity rows by the numeric JSON timestamp.
        # A partial expression index avoids scanning and casting every state record.
        """
        CREATE INDEX IF NOT EXISTS state_records_activity_age_idx
            ON state_records (
                namespace,
                ((record->>'last_used_at')::double precision)
            )
            WHERE record_type = 'table-activity'
        """,
        # A checkpoint-handoff token, parked by a source flow so a *different* flow --
        # one with a fresh Spark checkpoint after an SCD1->append switch or a destination
        # relocation -- can resume the CDC stream at the exact offset the old flow stopped
        # at, instead of re-snapshotting. Keyed by (namespace, table_key, channel), all
        # derived from the source only, so it is visible to any flow reading that source
        # table regardless of destination or flow type. Mutable (re-capture overwrites) and
        # deletable (consumed once the new flow has committed the seed), unlike the
        # write-once state_records. Populated by the table.migration option.
        """
        CREATE TABLE IF NOT EXISTS cdc_handoff (
            namespace   text        NOT NULL,
            table_key   text        NOT NULL,
            channel     smallint    NOT NULL DEFAULT 0,
            offset_json text        NOT NULL,
            schema_fp   text        NOT NULL,
            created_at  timestamptz NOT NULL DEFAULT now(),
            PRIMARY KEY (namespace, table_key, channel)
        )
        """,
    )


    def ensure_schema(connection: Any) -> None:
        # Docstring: Create the state tables if they do not already exist.
        #
        # Serialized on a transaction-scoped advisory lock: ``CREATE TABLE IF NOT EXISTS``
        # is *not* concurrency-safe on first creation -- when a Lakeflow pipeline starts one
        # Python worker per flow and they all create a brand-new table at once (the first run
        # after a table is added), the existence check passes for all of them and every worker
        # but one then fails inserting the catalog row with ``duplicate key ... pg_type_typname
        # _nsp_index``. The lock makes the losers wait, so they find the objects already present.
        # It needs no connector schema and is released by the commit below, so it is safe during
        # first provisioning; the key is distinct from the role-provisioning lock's.

        with connection.cursor() as cursor:
            cursor.execute(
                "SELECT pg_advisory_xact_lock(hashtextextended(%s, 0))",
                ("lakeflow-informix-ensure-schema",),
            )
            for statement in _SCHEMA_STATEMENTS:
                cursor.execute(statement)
        connection.commit()


    def seed_slots(connection: Any, namespace: str, slot_count: int) -> None:
        # Docstring: Ensure ``slot_count`` rows exist for ``namespace``.
        #
        # Capacity is the row count, so seeding *is* configuring the semaphore. Rows
        # are only ever added: removing them while a holder is live would silently
        # revoke a lease, so a reduced limit is enforced by the acquire query's
        # ``slot_id`` bound instead.

        with connection.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO conn_slots (namespace, slot_id)
                SELECT %s, generated.slot_id
                FROM generate_series(0, %s - 1) AS generated(slot_id)
                ON CONFLICT (namespace, slot_id) DO NOTHING
                """,
                (namespace, slot_count),
            )
        connection.commit()


    class LakebaseState:
        # Docstring: Connection factory and provisioning entry point for Lakebase state.
        #
        # One instance per reader process. Provisioning runs at most once per project
        # per process behind a lock, so the 60-odd flows a pipeline starts converge on
        # a single set of control-plane calls instead of each issuing their own.

        _provisioned: dict[str, dict[str, Any]] = {}
        # Held in a dict and built on first use rather than at class creation. Spark
        # cloudpickles the reader class, and the merged single-file deployment puts this
        # class in the same namespace the reader closes over, so a lock alive at import
        # would travel with it and make serialization fail outright ("cannot pickle
        # '_thread.lock' object"). Mutating a dict also avoids rebinding a name, which
        # the merged form -- where module globals become function locals -- cannot do.
        _provision_locks: dict[str, threading.Lock] = {}
        _project_gc_checked: dict[str, float] = {}

        @classmethod
        def _lock(cls) -> threading.Lock:
            lock = cls._provision_locks.get("provision")
            if lock is None:
                # setdefault resolves the race: racing callers may each build a lock,
                # but all of them return whichever one landed first.
                lock = cls._provision_locks.setdefault("provision", threading.Lock())
            return lock

        def __init__(self, options: dict[str, str], connection_identity: str) -> None:
            self._options = options
            self._project_id = options.get(
                "lakebase.project.id", ""
            ).strip() or project_id_for_connection(connection_identity)
            self._min_cu = float(options.get("lakebase.autoscale.min.cu", _DEFAULT_MIN_CU))
            self._max_cu = float(options.get("lakebase.autoscale.max.cu", _DEFAULT_MAX_CU))
            self._suspend_seconds = int(
                options.get("lakebase.suspend.timeout.seconds", _DEFAULT_SUSPEND_SECONDS)
            )
            self._provision_timeout_seconds = float(
                options.get("lakebase.provision.timeout.seconds", _DEFAULT_PROVISION_TIMEOUT_SECONDS)
            )
            if (
                not math.isfinite(self._provision_timeout_seconds)
                or self._provision_timeout_seconds <= 0
            ):
                raise ValueError("Option 'lakebase.provision.timeout.seconds' must be > 0")
            self._database = options.get("lakebase.database", _DEFAULT_DATABASE)
            # Two distinct identities, deliberately separate.
            #
            # The *state* identity is long-lived and does all ordinary state access, so
            # nothing in the steady-state path can expire mid-stream. Its role name is
            # fixed; only its password is configured. The *admin* identity is used only
            # to provision that role -- create it or reset its password -- and needs the
            # elevated rights to do so. Keeping them apart means the credential
            # distributed to every reader process is not one that can create roles.
            self._user_id = STATE_ROLE
            self._password = options.get("lakebase.password", "").strip()
            self._admin_password = options.get("lakebase.admin_password", "").strip()
            self._api: _WorkspaceApi | None = None
            self._facts: dict[str, Any] | None = None
            self._token: str | None = None
            self._token_minted_at = 0.0

        @property
        def project_id(self) -> str:
            return self._project_id

        def _api_client(self) -> _WorkspaceApi:
            if self._api is None:
                host, token = _workspace_credentials(self._options)
                self._api = _WorkspaceApi(host, token)
            return self._api

        def provision(self) -> dict[str, Any]:
            # Docstring: Idempotently ensure the project, endpoint, and schema all exist.

            cached = LakebaseState._provisioned.get(self._project_id)
            if cached is not None:
                self._facts = cached
                return cached
            deadline = time.monotonic() + self._provision_timeout_seconds
            lock = LakebaseState._lock()
            if not lock.acquire(timeout=self._provision_timeout_seconds):
                raise LakebaseStateError(
                    f"Lakebase provisioning timed out after {self._provision_timeout_seconds:g}s "
                    f"waiting for the provisioning lock for project {self._project_id}"
                )
            try:
                cached = LakebaseState._provisioned.get(self._project_id)
                if cached is not None:
                    self._facts = cached
                    return cached
                api = self._api_client()
                facts = ensure_project(
                    api,
                    self._project_id,
                    min_cu=self._min_cu,
                    max_cu=self._max_cu,
                    suspend_seconds=self._suspend_seconds,
                    deadline=deadline,
                )
                self._facts = facts
                self._ensure_password_login(facts)
                connection = self.connect()
                try:
                    ensure_schema(connection)
                finally:
                    connection.close()
                LakebaseState._provisioned[self._project_id] = facts
                return facts
            except LakebaseStateError as error:
                raise LakebaseStateError(
                    f"Lakebase provisioning failed for project {self._project_id}: {error}"
                ) from error
            finally:
                lock.release()

        def _password_login_works(self, facts: dict[str, Any]) -> bool:
            # Docstring: Return whether the configured user_id/password can actually log in.

            try:
                connection = self._open(facts, self._user_id, self._password)
            except Exception:
                # Postgres reports an absent role and a wrong password identically
                # ("password authentication failed for user ..."), with no SQLSTATE
                # to separate them, so this deliberately does not try to classify the
                # failure. Which repair is needed is decided by querying pg_roles.
                _LOGGER.debug("Lakebase password login failed for %s", self._user_id, exc_info=True)
                return False
            connection.close()
            return True

        def _ensure_password_login(self, facts: dict[str, Any]) -> None:
            # Docstring: Validate the state role's login, provisioning it if it fails.

            if not self._password:
                raise LakebaseStateError(
                    "Lakebase state needs a password for its state role; set lakebase.password"
                )
            if self._password_login_works(facts):
                _LOGGER.info(
                    "Lakebase role %s authenticated with the configured password", self._user_id
                )
                return
            # Fall back to the admin identity, the only one able to create a role or
            # reset its password.
            admin = self._connect_as_admin(facts)
            try:
                action = ensure_login_role(admin, self._database, self._user_id, self._password)
            finally:
                admin.close()
            if not self._password_login_works(facts):
                raise LakebaseStateError(
                    f"Lakebase role {self._user_id} still cannot log in after being {action}; "
                    "check lakebase.password and that the project has native Postgres "
                    "login enabled"
                )
            _LOGGER.info("Lakebase role %s %s and validated", self._user_id, action)

        def _credential(self) -> str:
            now = time.monotonic()
            if self._token is None or now - self._token_minted_at > _CREDENTIAL_REFRESH_SECONDS:
                facts = self._facts or self.provision()
                self._token = generate_credential(self._api_client(), facts["endpoint"])
                self._token_minted_at = now
            return self._token

        def connect(self) -> Any:
            # Docstring: Open a Postgres connection, waking a suspended endpoint if needed.
            #
            # ``psycopg2`` is preinstalled on the Databricks runtime; ``psycopg`` (v3)
            # is accepted as an alternative so the module also works where only that
            # is present.

            facts = self._facts or self.provision()
            # Always the state role: its password needs no control-plane call and
            # cannot expire mid-stream. The admin identity is reached only through
            # ``_connect_as_admin``, during provisioning.
            return self._open(facts, self._user_id, self._password)

        def collect_unused_projects(self, retention_days: int, interval_hours: float) -> int:
            # Docstring: Delete inactive, auto-named connector projects once per scan interval.

            if self._options.get("lakebase.project.id", "").strip():
                return 0
            now = time.monotonic()
            cache_key = self._options.get("lakebase.workspace.host", "workspace")
            if now - self._project_gc_checked.get(cache_key, float("-inf")) < interval_hours * 3600:
                return 0
            self._project_gc_checked[cache_key] = now
            api = self._api_client()
            response = api.request("GET", "/api/2.0/postgres/projects") or {}
            projects = response if isinstance(response, list) else response.get("projects", [])
            deleted = 0
            for project in projects:
                name = str((project or {}).get("name") or (project or {}).get("id") or "")
                project_id = name.rsplit("/", 1)[-1]
                if not project_id.startswith(_AUTO_PROJECT_PREFIX) or project_id == self._project_id:
                    continue
                connection = None
                try:
                    facts = _endpoint_facts(api, project_id)
                    token = generate_credential(api, facts["endpoint"])
                    connection = self._open(facts, self._admin_user(), token)
                    with connection.cursor() as cursor:
                        cursor.execute(
                            """
                            SELECT
                              COUNT(*) FILTER (WHERE record_type = 'state-gc'),
                              COUNT(*) FILTER (WHERE record_type = 'table-activity'),
                              MAX((record->>'last_used_at')::double precision)
                                FILTER (WHERE record_type = 'table-activity')
                            FROM state_records
                            """
                        )
                        gc_rows, activity_rows, last_used = cursor.fetchone()
                    if not gc_rows or not activity_rows or last_used is None:
                        continue
                    if float(last_used) >= time.time() - retention_days * 86400:
                        continue
                except Exception:
                    _LOGGER.warning(
                        "Skipping Lakebase project GC candidate %s", project_id, exc_info=True
                    )
                    continue
                finally:
                    if connection is not None:
                        connection.close()
                operation = api.request("DELETE", f"/api/2.0/postgres/projects/{project_id}")
                api.await_operation(operation)
                LakebaseState._provisioned.pop(project_id, None)
                deleted += 1
            return deleted

        def _admin_user(self) -> str:
            # Docstring: Return the role name used for provisioning.
            #
            # ``_default_user`` already honours ``lakebase.admin_user`` first, so this
            # does not re-check it: two copies of the same precedence rule can disagree.

            return _default_user(self._options)

        def _connect_as_admin(self, facts: dict[str, Any]) -> Any:
            # Docstring: Connect as the provisioning identity.
            #
            # Prefers ``lakebase.admin_password`` when set, because a password works
            # even where a control-plane credential cannot be minted. Otherwise mints a
            # short-lived OAuth credential for the workspace identity, which is what
            # makes the zero-configuration case work.

            if self._admin_password:
                return self._open(facts, self._admin_user(), self._admin_password)
            return self._open(facts, self._admin_user(), self._credential())

        def _open(self, facts: dict[str, Any], user: str, password: str) -> Any:
            # Docstring: Connect as ``user``, waking a suspended endpoint if needed.

            parameters = {
                "host": facts["host"],
                "dbname": self._database,
                "user": user,
                "password": password,
                "sslmode": "require",
                "connect_timeout": _CONNECT_TIMEOUT_SECONDS,
                **_NO_CLIENT_CERTIFICATE,
            }
            try:
                import psycopg2  # noqa: PLC0415
            except ImportError:
                pass
            else:
                return psycopg2.connect(**parameters)
            try:
                import psycopg  # noqa: PLC0415
            except ImportError as error:  # pragma: no cover - depends on runtime
                raise LakebaseStateError(
                    "Lakebase state needs psycopg2 or psycopg installed on the runtime"
                ) from error
            return psycopg.connect(**parameters)


    # --- connection slots ------------------------------------------------------
    #
    # The whole Volume fencing protocol -- per-slot reservation directories,
    # owner-/pulse-/released-/mutating- markers, a three-stage rename fence, and
    # retired-/revoked- quarantine -- existed to emulate one atomic compare-and-swap.
    # These four statements are that CAS, so none of it is needed here.
    #
    # Acquisition takes the lowest eligible slot whose lease is free or expired.
    # ``FOR UPDATE SKIP LOCKED`` is what makes it safe under contention: a row a
    # concurrent acquirer is already mutating is skipped rather than waited on, so N
    # racers claim N distinct slots in one round trip each and none can observe a
    # half-applied claim. ``epoch`` increments on every claim and becomes the fencing
    # token: a holder that stalls past its lease and wakes up later cannot renew or
    # release, because its epoch no longer matches.
    #
    # Every claim goes through the fair waiter queue: a slot is eligible only when no live
    # waiter ranked ahead of this one is also eligible for it, so no waiter is lapped
    # indefinitely under contention. Ordering is per slot rather than global: the band
    # predicate (w.floor <= slot < w.ceiling) means an older waiter reserved to high slots does
    # not block a younger one from a low slot it could never use, so there is no cross-band
    # head-of-line blocking.
    #
    # Waiters are ranked by requester *class* in rotation, then by age. A per-namespace cursor
    # (slot_rr_cursor) records the class served last; ``rot`` ranks each live waiter's class by
    # cyclic distance *after* that cursor -- MOD(class - last - 1, N) -- so the class next in
    # rotation has rot 0 and is served first, then the next, wrapping around. One class per
    # grant, in rotation, so a class gets a turn every N grants no matter how many tickets
    # another class holds. That is what serving by arrival cannot do: because a served waiter
    # dequeues, the next same-class ticket would inherit the head and the high-volume class
    # would keep winning; the cursor rotates past a class once it is served, so a burst of
    # consumer tickets cannot crowd out the few CDC-daemon tickets. Within the chosen class the
    # oldest ticket wins (ticket_id tiebreak); empty classes are skipped for free since only
    # live waiters appear in ``live``. The ``live`` CTE drops tickets that stopped heartbeating
    # so a dead ticket cannot block a slot even between reaper sweeps, and a caller whose own
    # ticket is stale (``me`` empty) wins nothing until it heartbeats again. The ordering is
    # advisory: FOR UPDATE SKIP LOCKED + the epoch CAS serialise the actual grant, so a stale
    # cursor or a read race costs at most one extra sweep, never an over-issued slot. The
    # winner advances the cursor to its own class (see _ADVANCE_RR_CURSOR) in the same
    # transaction as the claim.
    #
    # ``num_classes`` is the rotation modulus (the count of distinct classes); ``1`` makes rot
    # uniformly 0, so waiters are served strictly by ticket age.
    _ACQUIRE_SLOT = """
    WITH cur AS (
        SELECT COALESCE(
            (SELECT last_class FROM slot_rr_cursor WHERE namespace = %(namespace)s), -1
        ) AS last_class
    ),
    live AS (
        SELECT ticket_id, floor, ceiling,
               MOD(waiter_class - (SELECT last_class FROM cur) - 1 + %(num_classes)s,
                   %(num_classes)s) AS rot
        FROM slot_waiters
        WHERE namespace = %(namespace)s
          AND heartbeat_at >= now() - make_interval(secs => %(waiter_ttl)s)
    ),
    me AS (
        SELECT rot, ticket_id FROM live WHERE ticket_id = %(ticket_id)s
    )
    UPDATE conn_slots SET owner = %(owner)s, epoch = epoch + 1,
                          scope = %(scope)s, renewed_at = now()
    WHERE (namespace, slot_id) = (
        SELECT s.namespace, s.slot_id FROM conn_slots s
        CROSS JOIN me
        WHERE s.namespace = %(namespace)s
          AND s.slot_id >= %(floor)s
          AND s.slot_id < %(ceiling)s
          AND (s.owner IS NULL OR s.renewed_at < now() - make_interval(secs => %(lease)s))
          AND NOT EXISTS (
              SELECT 1 FROM live w
              WHERE w.floor <= s.slot_id AND s.slot_id < w.ceiling
                AND (w.rot, w.ticket_id) < (me.rot, me.ticket_id)
          )
        ORDER BY s.slot_id
        FOR UPDATE SKIP LOCKED
        LIMIT 1
    )
    RETURNING slot_id, epoch
    """

    # Renewal is guarded on (owner, epoch): a zombie's heartbeat is rejected rather
    # than silently extending a lease its successor now owns. A caller that gets no
    # row has provably lost the slot and must stop using its connection.
    _HEARTBEAT_SLOT = """
    UPDATE conn_slots SET renewed_at = now()
    WHERE namespace = %(namespace)s AND slot_id = %(slot_id)s
      AND owner = %(owner)s AND epoch = %(epoch)s
    RETURNING slot_id
    """

    # Release carries the same guard, for a sharper reason: without it a zombie's
    # late release would free a slot its successor legitimately holds, over-issuing
    # capacity. On the Volume this hazard is what the mutating- marker guarded.
    _RELEASE_SLOT = """
    UPDATE conn_slots SET owner = NULL, scope = NULL, renewed_at = NULL
    WHERE namespace = %(namespace)s AND slot_id = %(slot_id)s
      AND owner = %(owner)s AND epoch = %(epoch)s
    RETURNING slot_id
    """

    # The winner stamps the cursor with its own class so the next grant rotates to the class
    # after it. Upsert because the row may not exist yet on the first grant in a namespace.
    _ADVANCE_RR_CURSOR = """
    INSERT INTO slot_rr_cursor (namespace, last_class) VALUES (%(namespace)s, %(waiter_class)s)
    ON CONFLICT (namespace) DO UPDATE SET last_class = EXCLUDED.last_class
    """

    # A waiter enqueues one ticket for the whole time it blocks, heartbeats it each sweep,
    # and deletes it the instant it wins a slot (or gives up). The heartbeat doubles as the
    # reaper -- it drops any ticket whose owner stopped heartbeating -- so a crashed or
    # timed-out waiter cannot wedge the queue and the table needs no separate GC.
    _ENQUEUE_WAITER = """
    INSERT INTO slot_waiters (namespace, owner, floor, ceiling, waiter_class)
    VALUES (%(namespace)s, %(owner)s, %(floor)s, %(ceiling)s, %(waiter_class)s)
    RETURNING ticket_id
    """
    _HEARTBEAT_WAITER = """
    UPDATE slot_waiters SET heartbeat_at = now()
    WHERE namespace = %(namespace)s AND ticket_id = %(ticket_id)s
    RETURNING ticket_id
    """
    _REAP_WAITERS = """
    DELETE FROM slot_waiters
    WHERE namespace = %(namespace)s
      AND heartbeat_at < now() - make_interval(secs => %(waiter_ttl)s)
    """
    _DEQUEUE_WAITER = """
    DELETE FROM slot_waiters WHERE namespace = %(namespace)s AND ticket_id = %(ticket_id)s
    """


    class ConnectionSlot:
        # Docstring: A held connection-capacity lease.
        #
        # ``epoch`` is the fencing token; it is required to renew or release, so a
        # lease that expired while this process was stalled cannot be resurrected.

        __slots__ = ("namespace", "slot_id", "epoch", "owner")

        def __init__(self, namespace: str, slot_id: int, epoch: int, owner: str) -> None:
            self.namespace = namespace
            self.slot_id = slot_id
            self.epoch = epoch
            self.owner = owner

        def __repr__(self) -> str:  # pragma: no cover - diagnostics only
            return f"ConnectionSlot(slot-{self.slot_id:04d}, epoch={self.epoch})"


    def acquire_slot(
        connection: Any,
        namespace: str,
        owner: str,
        *,
        slot_count: int,
        ticket_id: int,
        floor: int = 0,
        scope: str | None = None,
        lease_seconds: float = 120.0,
        waiter_ttl: float = _DEFAULT_WAITER_TTL_SECONDS,
        waiter_class: int = 0,
        num_classes: int = 1,
    ) -> ConnectionSlot | None:
        # Docstring: Claim one slot, or return ``None`` when every eligible slot is busy.
        #
        # ``floor`` keeps a reader off the low slots: the CDC daemon and the snapshot drain
        # pass their reservations so they can never claim a slot kept for consumer reads,
        # which is what makes a reservation a guarantee rather than a preference.
        # ``slot_count`` bounds the ceiling, so lowering the configured limit takes effect
        # immediately even though surplus rows are deliberately left in place.
        #
        # ``ticket_id`` is this caller's place in the fair queue: the id returned by
        # ``enqueue_waiter``, heartbeated with the same ``waiter_ttl``. The claim yields any
        # slot a waiter ranked ahead of it is also eligible for, so this caller waits its turn.
        # ``waiter_class`` is this caller's class (matching the ticket) and ``num_classes`` the
        # rotation modulus; on a win the cursor is advanced to ``waiter_class`` in the same
        # transaction as the claim.

        parameters = {
            "owner": owner,
            "scope": scope,
            "namespace": namespace,
            "floor": max(0, floor),
            "ceiling": slot_count,
            "lease": float(lease_seconds),
            "ticket_id": int(ticket_id),
            "waiter_ttl": float(waiter_ttl),
            "num_classes": max(1, int(num_classes)),
        }
        with connection.cursor() as cursor:
            cursor.execute(_ACQUIRE_SLOT, parameters)
            row = cursor.fetchone()
            if row is not None:
                # Advance the rotation cursor to this class inside the same transaction as the
                # claim, so the next grant rotates past it. Best-effort ordering only -- a lost
                # advance under a race just repeats a class, never over-issues a slot.
                cursor.execute(
                    _ADVANCE_RR_CURSOR,
                    {"namespace": namespace, "waiter_class": int(waiter_class)},
                )
        connection.commit()
        if row is None:
            return None
        return ConnectionSlot(namespace, int(row[0]), int(row[1]), owner)


    def enqueue_waiter(
        connection: Any,
        namespace: str,
        owner: str,
        *,
        floor: int,
        ceiling: int,
        waiter_class: int = 0,
    ) -> int:
        # Docstring: Register this caller as a slot waiter and return its queue ticket.
        #
        # The ticket records the eligible band [floor, ceiling); acquisition consults it
        # so a waiter ranked ahead in the same band is served first. ``waiter_class`` tags
        # the ticket with its requester class for the rotation; it defaults to 0, the
        # consumer class. Commit it before waiting so other waiters' connections can see it.

        with connection.cursor() as cursor:
            cursor.execute(
                _ENQUEUE_WAITER,
                {
                    "namespace": namespace,
                    "owner": owner,
                    "floor": max(0, floor),
                    "ceiling": int(ceiling),
                    "waiter_class": int(waiter_class),
                },
            )
            row = cursor.fetchone()
        connection.commit()
        return int(row[0])


    def heartbeat_waiter(connection: Any, namespace: str, ticket_id: int, *, waiter_ttl: float) -> bool:
        # Docstring: Renew this waiter's ticket and reap any whose owner stopped heartbeating.
        #
        # Folding the reap into the heartbeat keeps the queue self-cleaning: a crashed or
        # timed-out waiter's ticket ages out and is dropped by the next live heartbeat, so
        # it never blocks the queue and no separate GC pass is needed. Returns False when
        # the ticket no longer exists (it was reaped after a stall longer than
        # ``waiter_ttl``): acquisition only ever grants to a live ticket, so the caller must
        # enqueue a fresh one.

        with connection.cursor() as cursor:
            cursor.execute(
                _HEARTBEAT_WAITER,
                {"namespace": namespace, "ticket_id": int(ticket_id)},
            )
            renewed = cursor.fetchone() is not None
            cursor.execute(
                _REAP_WAITERS,
                {"namespace": namespace, "waiter_ttl": float(waiter_ttl)},
            )
        connection.commit()
        return renewed


    def dequeue_waiter(connection: Any, namespace: str, ticket_id: int) -> None:
        # Docstring: Remove this waiter's ticket -- on winning a slot or on giving up.

        with connection.cursor() as cursor:
            cursor.execute(
                _DEQUEUE_WAITER,
                {"namespace": namespace, "ticket_id": int(ticket_id)},
            )
        connection.commit()


    _PUT_CDC_HANDOFF = """
    INSERT INTO cdc_handoff (namespace, table_key, channel, offset_json, schema_fp)
    VALUES (%(namespace)s, %(table_key)s, %(channel)s, %(offset_json)s, %(schema_fp)s)
    ON CONFLICT (namespace, table_key, channel)
    DO UPDATE SET offset_json = EXCLUDED.offset_json,
                  schema_fp = EXCLUDED.schema_fp,
                  created_at = now()
    """

    _GET_CDC_HANDOFF = """
    SELECT offset_json, schema_fp FROM cdc_handoff
    WHERE namespace = %(namespace)s AND table_key = %(table_key)s AND channel = %(channel)s
    """

    _DELETE_CDC_HANDOFF = """
    DELETE FROM cdc_handoff
    WHERE namespace = %(namespace)s AND table_key = %(table_key)s AND channel = %(channel)s
    """


    def put_cdc_handoff(
        connection: Any,
        namespace: str,
        table_key: str,
        channel: int,
        offset_json: str,
        schema_fp: str,
    ) -> None:
        # Docstring: Park (or overwrite) a table's checkpoint-handoff token. Idempotent re-capture.

        with connection.cursor() as cursor:
            cursor.execute(
                _PUT_CDC_HANDOFF,
                {
                    "namespace": namespace,
                    "table_key": table_key,
                    "channel": int(channel),
                    "offset_json": offset_json,
                    "schema_fp": schema_fp,
                },
            )
        connection.commit()


    def get_cdc_handoff(
        connection: Any, namespace: str, table_key: str, channel: int
    ) -> dict[str, str] | None:
        # Docstring: Return the parked ``{offset_json, schema_fp}`` token, or ``None`` when absent.

        with connection.cursor() as cursor:
            cursor.execute(
                _GET_CDC_HANDOFF,
                {"namespace": namespace, "table_key": table_key, "channel": int(channel)},
            )
            row = cursor.fetchone()
        connection.commit()
        if row is None:
            return None
        return {"offset_json": row[0], "schema_fp": row[1]}


    def delete_cdc_handoff(connection: Any, namespace: str, table_key: str, channel: int) -> None:
        # Docstring: Remove a consumed handoff token. Idempotent (a missing row is a no-op).

        with connection.cursor() as cursor:
            cursor.execute(
                _DELETE_CDC_HANDOFF,
                {"namespace": namespace, "table_key": table_key, "channel": int(channel)},
            )
        connection.commit()


    def heartbeat_slot(connection: Any, slot: ConnectionSlot) -> bool:
        # Docstring: Renew a lease. ``False`` means the lease was lost and must not be reused.

        with connection.cursor() as cursor:
            cursor.execute(
                _HEARTBEAT_SLOT,
                {
                    "namespace": slot.namespace,
                    "slot_id": slot.slot_id,
                    "owner": slot.owner,
                    "epoch": slot.epoch,
                },
            )
            renewed = cursor.fetchone() is not None
        connection.commit()
        return renewed


    def release_slot(connection: Any, slot: ConnectionSlot) -> bool:
        # Docstring: Free a lease. ``False`` means it had already been reclaimed.

        with connection.cursor() as cursor:
            cursor.execute(
                _RELEASE_SLOT,
                {
                    "namespace": slot.namespace,
                    "slot_id": slot.slot_id,
                    "owner": slot.owner,
                    "epoch": slot.epoch,
                },
            )
            released = cursor.fetchone() is not None
        connection.commit()
        return released


    # A monotonic "the pool is recycling slots" token. ``epoch`` increments on every claim
    # (see ``_ACQUIRE_SLOT``: ``epoch = epoch + 1``), so the sum over a namespace strictly
    # increases each time any slot is acquired -- and a freed slot is only re-acquired when
    # a waiter wins it, so a rising sum means work is completing and capacity is turning
    # over. A caller that cannot win a slot can poll this between sweeps to tell "the pool
    # is busy (turning over) -- keep waiting" from "the pool is wedged (frozen) -- give up",
    # without needing to see which slot moved. A slot merely held (a long read that neither
    # releases nor re-claims) does not advance it: that is deliberate, the token measures
    # forward progress of the pool, not liveness of an individual holder.
    _POOL_PROGRESS_TOKEN = """
    SELECT COALESCE(SUM(epoch), 0) FROM conn_slots WHERE namespace = %(namespace)s
    """


    def pool_progress_token(connection: Any, namespace: str) -> int:
        # Docstring: Return the pool's turnover token (see ``_POOL_PROGRESS_TOKEN``).

        with connection.cursor() as cursor:
            cursor.execute(_POOL_PROGRESS_TOKEN, {"namespace": namespace})
            row = cursor.fetchone()
        # Commit so the next poll sees a fresh snapshot rather than this transaction's.
        connection.commit()
        return int(row[0]) if row and row[0] is not None else 0


    # --- backlog hints ---------------------------------------------------------
    #
    # One row per table, and ``GREATEST`` makes the write monotonic. The Volume
    # version needed a quantised bucket directory per 15s, a walk-back over recent
    # buckets on read, and a reaper for old generations -- all to approximate
    # last-writer-wins on a filesystem with no atomic update. A single upsert is
    # exact, and one query returns every table's hint instead of walking a directory
    # per table.
    _WRITE_HINT = """
    INSERT INTO backlog_hints (namespace, table_name, lsn, updated_at)
    VALUES (%(namespace)s, %(table_name)s, %(lsn)s, now())
    ON CONFLICT (namespace, table_name) DO UPDATE
       SET lsn = GREATEST(backlog_hints.lsn, EXCLUDED.lsn), updated_at = now()
    """

    _READ_HINTS = """
    SELECT table_name, lsn FROM backlog_hints
    WHERE namespace = %(namespace)s
      AND updated_at > now() - make_interval(secs => %(max_age)s)
    """


    def publish_backlog_hint(connection: Any, namespace: str, table_name: str, lsn: int) -> None:
        # Docstring: Record a table's log position, never regressing an existing value.

        with connection.cursor() as cursor:
            cursor.execute(
                _WRITE_HINT, {"namespace": namespace, "table_name": table_name, "lsn": int(lsn)}
            )
        connection.commit()


    def read_backlog_hints(
        connection: Any, namespace: str, *, max_age_seconds: float = 45.0
    ) -> dict[str, int]:
        # Docstring: Return every fresh hint for a namespace in one round trip.
        #
        # Stale rows are filtered by age rather than deleted: a hint is advisory, and
        # leaving it costs one row per table instead of a reaper.

        with connection.cursor() as cursor:
            cursor.execute(_READ_HINTS, {"namespace": namespace, "max_age": float(max_age_seconds)})
            rows = cursor.fetchall()
        # End the read-only transaction so the connection is never left idle-in-transaction.
        connection.rollback()
        return {str(name): int(lsn) for name, lsn in rows}


    # --- connection limit configuration ---------------------------------------

    _WRITE_LIMIT = """
    INSERT INTO conn_limits (namespace, max_connections, reserved_deletes, version, updated_at)
    VALUES (%(namespace)s, %(max_connections)s, 0, %(version)s, now())
    ON CONFLICT (namespace) DO UPDATE
       SET max_connections = EXCLUDED.max_connections,
           reserved_deletes = 0,
           version = EXCLUDED.version,
           updated_at = now()
    """


    def publish_connection_limit(
        connection: Any,
        namespace: str,
        max_connections: int,
        version: int,
    ) -> None:
        # Docstring: Publish the agreed capacity configuration for a namespace.

        with connection.cursor() as cursor:
            cursor.execute(
                _WRITE_LIMIT,
                {
                    "namespace": namespace,
                    "max_connections": int(max_connections),
                    "version": int(version),
                },
            )
        connection.commit()


    def read_connection_limit(connection: Any, namespace: str) -> dict[str, int] | None:
        # Docstring: Return the published capacity configuration, or ``None`` if unset.

        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT max_connections, version
                FROM conn_limits WHERE namespace = %(namespace)s
                """,
                {"namespace": namespace},
            )
            row = cursor.fetchone()
        # End the read-only transaction so the connection is never left idle-in-transaction.
        connection.rollback()
        if row is None:
            return None
        return {
            "max_connections": int(row[0]),
            "version": int(row[1]),
        }


    # --- immutable state records ----------------------------------------------
    #
    # ``INSERT ... ON CONFLICT DO NOTHING RETURNING`` is the head election. Exactly
    # one writer gets a row back; every other writer gets nothing and re-reads the
    # winner. That single statement replaces writing a candidate file, fsyncing it,
    # and renaming it into an exclusive ``head`` -- along with the candidate sweeper
    # that had to clean up whichever candidates lost.
    _INSERT_RECORD = """
    INSERT INTO state_records (namespace, record_key, record, record_type)
    VALUES (%(namespace)s, %(record_key)s, %(record)s::jsonb, %(record_type)s)
    ON CONFLICT (namespace, record_key) DO NOTHING
    RETURNING record
    """

    _SELECT_RECORD = """
    SELECT record FROM state_records
    WHERE namespace = %(namespace)s AND record_key = %(record_key)s
    """

    _DELETE_OBSOLETE_SCOPED_RECORDS = """
    DELETE FROM state_records
    WHERE namespace = %(namespace)s
      AND record_key LIKE %(record_key_pattern)s
      AND record->>'scope' LIKE %(pipeline_scope_pattern)s
      AND record->>'scope' <> %(current_scope)s
      -- Cast the nullable parameter to text so Postgres can determine its type:
      -- a NULL retained_scope is sent with an unknown type OID, and `$n IS NULL`
      -- alone gives the planner nothing to infer from (AmbiguousParameter otherwise).
      AND (%(retained_scope)s::text IS NULL OR record->>'scope' <> %(retained_scope)s::text)
    RETURNING record_key
    """

    _TOUCH_TABLE_ACTIVITY = """
    INSERT INTO state_records (namespace, record_key, record, record_type)
    VALUES (
      %(namespace)s, %(record_key)s,
      jsonb_build_object(
        -- Cast the string parameters: jsonb_build_object value arguments are typed
        -- "any", so an uncast parameter has no determinable type when the statement
        -- is prepared (IndeterminateDatatype: could not determine data type of $n).
        'format_version', 1, 'pipeline_id', %(pipeline_id)s::text,
        'table_prefix', %(table_prefix)s::text,
        'last_used_at', extract(epoch FROM clock_timestamp())
      ),
      'table-activity'
    )
    ON CONFLICT (namespace, record_key) DO UPDATE
    SET record = EXCLUDED.record
    WHERE state_records.record_type = 'table-activity'
      AND (state_records.record->>'last_used_at')::double precision
          <= extract(epoch FROM clock_timestamp()) - %(touch_interval_seconds)s
    RETURNING record
    """

    _CLAIM_STATE_GC = """
    INSERT INTO state_records (namespace, record_key, record, record_type)
    VALUES (
      %(namespace)s, %(record_key)s,
      jsonb_build_object(
        'format_version', 1,
        'last_run_at', extract(epoch FROM clock_timestamp()),
        'next_run_at', extract(epoch FROM clock_timestamp()) + %(gc_interval_seconds)s
      ),
      'state-gc'
    )
    ON CONFLICT (namespace, record_key) DO UPDATE
    SET record = EXCLUDED.record
    WHERE state_records.record_type = 'state-gc'
      AND (state_records.record->>'next_run_at')::double precision
          <= extract(epoch FROM clock_timestamp())
    RETURNING record
    """

    _DELETE_STALE_PIPELINE_STATE = """
    DELETE FROM state_records AS target
    USING state_records AS activity
    WHERE target.namespace = %(namespace)s
      AND activity.namespace = target.namespace
      AND activity.record_type = 'table-activity'
      AND (activity.record->>'last_used_at')::double precision < %(cutoff_epoch)s
      AND target.record_key LIKE activity.record->>'table_prefix' || '/%%'
      AND target.record->>'scope' LIKE activity.record->>'pipeline_id' || '_@_%%'
    RETURNING target.record_key
    """

    _DELETE_UNUSED_TABLE_STATE = """
    DELETE FROM state_records AS target
    WHERE target.namespace = %(namespace)s
      AND target.record_type NOT IN ('table-activity', 'state-gc')
      AND EXISTS (
        SELECT 1 FROM state_records AS stale
        WHERE stale.namespace = target.namespace
          AND stale.record_type = 'table-activity'
          AND (stale.record->>'last_used_at')::double precision < %(cutoff_epoch)s
          AND target.record_key LIKE stale.record->>'table_prefix' || '/%%'
      )
      AND NOT EXISTS (
        SELECT 1 FROM state_records AS active
        WHERE active.namespace = target.namespace
          AND active.record_type = 'table-activity'
          AND (active.record->>'last_used_at')::double precision >= %(cutoff_epoch)s
          AND target.record_key LIKE active.record->>'table_prefix' || '/%%'
      )
    RETURNING target.record_key
    """

    _DELETE_STALE_ACTIVITY = """
    DELETE FROM state_records
    WHERE namespace = %(namespace)s
      AND record_type = 'table-activity'
      AND (record->>'last_used_at')::double precision < %(cutoff_epoch)s
    RETURNING record_key
    """

    _PUBLISH_MINIMUM_LSN_RECORD = """
    INSERT INTO state_records (namespace, record_key, record, record_type)
    VALUES (%(namespace)s, %(record_key)s, %(record)s::jsonb, %(record_type)s)
    ON CONFLICT (namespace, record_key) DO UPDATE
    SET record = EXCLUDED.record
    WHERE state_records.record_type = EXCLUDED.record_type
      AND state_records.record->>'format_version' = EXCLUDED.record->>'format_version'
      AND state_records.record->>'scope' = EXCLUDED.record->>'scope'
      AND state_records.record->>'table' = EXCLUDED.record->>'table'
      AND (state_records.record->>'start_lsn')::numeric
          > (EXCLUDED.record->>'start_lsn')::numeric
    RETURNING record
    """


    # Scope-independent counterpart of the minimum publisher: converge one key on the
    # *highest* start_lsn, and match on table alone (no scope) because the record is
    # shared across every update scope for the table. Used for the delete-bootstrap
    # snapshot floor, which must move forward only when a resnapshot repopulates the
    # destination as-of a later boundary.
    _PUBLISH_MAXIMUM_LSN_RECORD = """
    INSERT INTO state_records (namespace, record_key, record, record_type)
    VALUES (%(namespace)s, %(record_key)s, %(record)s::jsonb, %(record_type)s)
    ON CONFLICT (namespace, record_key) DO UPDATE
    SET record = EXCLUDED.record
    WHERE state_records.record_type = EXCLUDED.record_type
      AND state_records.record->>'format_version' = EXCLUDED.record->>'format_version'
      AND state_records.record->>'table' = EXCLUDED.record->>'table'
      AND (state_records.record->>'start_lsn')::numeric
          < (EXCLUDED.record->>'start_lsn')::numeric
    RETURNING record
    """


    # Resolved once and cached, but in a dict mutated in place -- never a bare module
    # global rebound via ``global``. The single-file merged deployment nests this whole
    # module inside a function, turning module globals into that function's locals, so a
    # ``global`` rebinding helper would address a name nothing ever assigns and raise
    # ``NameError`` at runtime (mirrors _LAKEBASE_WAITER_LOCK in informix.py). Mutating a
    # dict needs no rebinding, so it survives both the standalone and merged forms.
    _CONNECTION_LOST_ERROR_TYPES: dict[str, tuple[type[BaseException], ...]] = {}


    def connection_lost_error_types() -> tuple[type[BaseException], ...]:
        # Docstring: Return the driver exception types raised when a connection is severed.
        #
        # A Lakebase (Postgres) connection left idle -- e.g. across a long wait for
        # connection capacity -- is reaped by the server, and the next query on it
        # fails with ``OperationalError`` ("SSL SYSCALL error: EOF detected", "server
        # closed the connection unexpectedly") or ``InterfaceError`` ("connection
        # already closed"). Callers catch these to reconnect and retry an idempotent
        # state operation. Resolved once against whichever driver is installed
        # (``psycopg2`` or ``psycopg`` v3); an empty tuple when neither is importable
        # so the caller simply never matches and propagates.

        cached = _CONNECTION_LOST_ERROR_TYPES.get("types")
        if cached is not None:
            return cached
        types: list[type[BaseException]] = []
        for module_name in ("psycopg2", "psycopg"):
            try:
                module = __import__(module_name)
            except ImportError:
                continue
            for attribute in ("OperationalError", "InterfaceError"):
                error_type = getattr(module, attribute, None)
                if isinstance(error_type, type) and issubclass(error_type, BaseException):
                    types.append(error_type)
        # setdefault resolves the race: concurrent callers may each resolve the tuple,
        # but every one returns whichever landed first.
        return _CONNECTION_LOST_ERROR_TYPES.setdefault("types", tuple(types))


    def publish_state_record(
        connection: Any,
        namespace: str,
        record_key: str,
        record: dict[str, Any],
        *,
        record_type: str = "generic",
    ) -> dict[str, Any]:
        # Docstring: Elect exactly one record for a key and return the elected value.
        #
        # Always returns the *winning* record, which may be another writer's. Callers
        # depend on that: a record is the shared truth for a key, so a loser must adopt
        # the winner rather than assume its own value took effect.

        payload = json.dumps(record, sort_keys=True)
        with connection.cursor() as cursor:
            cursor.execute(
                _INSERT_RECORD,
                {
                    "namespace": namespace,
                    "record_key": record_key,
                    "record": payload,
                    "record_type": record_type,
                },
            )
            row = cursor.fetchone()
            if row is None:
                cursor.execute(_SELECT_RECORD, {"namespace": namespace, "record_key": record_key})
                row = cursor.fetchone()
        connection.commit()
        if row is None:
            # The row existed for the conflict yet vanished before the re-read. Only
            # an external deletion can do this, and silently returning the caller's
            # own unelected value would let two readers disagree about shared truth.
            raise LakebaseStateError(f"state record {namespace}/{record_key} vanished during election")
        return _as_dict(row[0])


    def publish_minimum_lsn_state_record(
        connection: Any,
        namespace: str,
        record_key: str,
        record: dict[str, Any],
        *,
        record_type: str,
    ) -> dict[str, Any]:
        # Docstring: Atomically publish the lowest compatible ``start_lsn`` for one key.
        #
        # A later CDC poll can discover an older still-open transaction, moving its
        # effective restart position backwards. PostgreSQL serializes the conflict
        # update so concurrent upsert workers converge on the minimum. Incompatible
        # identity metadata prevents the update; schema metadata travels with the
        # winning minimum because schema transitions can legitimately occur later in
        # the same update.

        payload = json.dumps(record, sort_keys=True)
        parameters = {
            "namespace": namespace,
            "record_key": record_key,
            "record": payload,
            "record_type": record_type,
        }
        with connection.cursor() as cursor:
            cursor.execute(_PUBLISH_MINIMUM_LSN_RECORD, parameters)
            row = cursor.fetchone()
            if row is None:
                cursor.execute(_SELECT_RECORD, parameters)
                row = cursor.fetchone()
        connection.commit()
        if row is None:
            raise LakebaseStateError(
                f"state record {namespace}/{record_key} vanished during minimum-LSN publication"
            )
        return _as_dict(row[0])


    def publish_maximum_lsn_state_record(
        connection: Any,
        namespace: str,
        record_key: str,
        record: dict[str, Any],
        *,
        record_type: str,
    ) -> dict[str, Any]:
        # Docstring: Atomically publish the highest compatible ``start_lsn`` for one key.
        #
        # The scope-independent counterpart of :func:`publish_minimum_lsn_state_record`,
        # used for the delete-bootstrap snapshot floor: the floor must advance only when a
        # resnapshot repopulates the destination as-of a later boundary, and stay put
        # otherwise. PostgreSQL serializes the conflict update so concurrent publishers
        # converge on the maximum.

        payload = json.dumps(record, sort_keys=True)
        parameters = {
            "namespace": namespace,
            "record_key": record_key,
            "record": payload,
            "record_type": record_type,
        }
        with connection.cursor() as cursor:
            cursor.execute(_PUBLISH_MAXIMUM_LSN_RECORD, parameters)
            row = cursor.fetchone()
            if row is None:
                cursor.execute(_SELECT_RECORD, parameters)
                row = cursor.fetchone()
        connection.commit()
        if row is None:
            raise LakebaseStateError(
                f"state record {namespace}/{record_key} vanished during maximum-LSN publication"
            )
        return _as_dict(row[0])


    def read_state_record(connection: Any, namespace: str, record_key: str) -> dict[str, Any] | None:
        # Docstring: Return an elected record, or ``None`` when the key is unwritten.

        with connection.cursor() as cursor:
            cursor.execute(_SELECT_RECORD, {"namespace": namespace, "record_key": record_key})
            row = cursor.fetchone()
        # End the implicit transaction a bare SELECT opens. Without this the connection
        # is left "idle in transaction" and Lakebase reaps it after
        # idle_in_transaction_session_timeout -- fatal when a caller interleaves a slow
        # non-Lakebase step (a full-table snapshot scan) before its next state write.
        connection.rollback()
        if row is None:
            return None
        return _as_dict(row[0])


    def delete_obsolete_scoped_state_records(
        connection: Any,
        namespace: str,
        record_key_prefix: str,
        pipeline_scope_prefix: str,
        current_scope: str,
        retained_scope: str | None = None,
    ) -> int:
        # Docstring: Delete old update scopes while preserving the scope in Spark's checkpoint.

        with connection.cursor() as cursor:
            cursor.execute(
                _DELETE_OBSOLETE_SCOPED_RECORDS,
                {
                    "namespace": namespace,
                    "record_key_pattern": f"{record_key_prefix}/%",
                    "pipeline_scope_pattern": f"{pipeline_scope_prefix}%",
                    "current_scope": current_scope,
                    "retained_scope": retained_scope,
                },
            )
            deleted = len(cursor.fetchall())
        connection.commit()
        return deleted


    def touch_table_activity(
        connection: Any,
        namespace: str,
        record_key: str,
        table_prefix: str,
        pipeline_id: str,
        touch_interval_seconds: float,
    ) -> bool:
        # Docstring: Refresh one table/pipeline activity record when its write interval elapsed.

        with connection.cursor() as cursor:
            cursor.execute(
                _TOUCH_TABLE_ACTIVITY,
                {
                    "namespace": namespace,
                    "record_key": record_key,
                    "table_prefix": table_prefix,
                    "pipeline_id": pipeline_id,
                    "touch_interval_seconds": touch_interval_seconds,
                },
            )
            touched = cursor.fetchone() is not None
        connection.commit()
        return touched


    def collect_stale_table_state(
        connection: Any,
        namespace: str,
        gc_record_key: str,
        retention_days: int,
        gc_interval_hours: float,
    ) -> int:
        # Docstring: Run at most one database-scoped table-state collection per interval.

        with connection.cursor() as cursor:
            cursor.execute(
                _CLAIM_STATE_GC,
                {
                    "namespace": namespace,
                    "record_key": gc_record_key,
                    "gc_interval_seconds": gc_interval_hours * 3600,
                },
            )
            if cursor.fetchone() is None:
                connection.commit()
                return 0
            cursor.execute("SELECT extract(epoch FROM clock_timestamp())")
            cutoff_epoch = float(cursor.fetchone()[0]) - retention_days * 86400
            parameters = {"namespace": namespace, "cutoff_epoch": cutoff_epoch}
            deleted = 0
            for statement in (
                _DELETE_STALE_PIPELINE_STATE,
                _DELETE_UNUSED_TABLE_STATE,
                _DELETE_STALE_ACTIVITY,
            ):
                cursor.execute(statement, parameters)
                deleted += len(cursor.fetchall())
        connection.commit()
        return deleted


    def _as_dict(value: Any) -> dict[str, Any]:
        # Docstring: Normalise a jsonb column, which drivers return as dict or as text.

        if isinstance(value, dict):
            return value
        decoded = json.loads(value)
        if not isinstance(decoded, dict):
            raise LakebaseStateError("state record is not a JSON object")
        return decoded


    def _default_user(options: dict[str, str]) -> str:
        # Docstring: Resolve the provisioning role name, which is the caller's own identity.
        #
        # The last two resolutions exist because the process that needs this name has
        # no ambient identity: ``WorkspaceClient()`` cannot be constructed there, so
        # asking the SDK who we are is not an option. Instead the driver's captured
        # credential is used to *ask the control plane*, which works from anywhere,
        # with the SDK kept only for the non-pipeline case.

        explicit = options.get("lakebase.admin_user", "").strip()
        if explicit:
            return explicit
        client_id = os.environ.get("DATABRICKS_CLIENT_ID", "").strip()
        if client_id:
            return client_id
        identity = _current_user_from_captured_credential(options)
        if identity:
            return identity
        try:
            from databricks.sdk import WorkspaceClient  # noqa: PLC0415

            return WorkspaceClient().current_user.me().user_name
        except Exception as error:  # pragma: no cover - depends on runtime
            raise LakebaseStateError(
                "Cannot determine the Lakebase provisioning role; set lakebase.admin_user"
            ) from error


    def _current_user_from_captured_credential(options: dict[str, str]) -> str:
        # Docstring: Return the calling identity's user name, or "" if it cannot be resolved.
        #
        # A service principal has no ``userName``, so ``id`` is accepted as the
        # fallback: for one, that is the client id the Postgres role is named after.

        try:
            host, token = _workspace_credentials(options)
            response = _WorkspaceApi(host, token).request(
                "GET", "/api/2.0/preview/scim/v2/Me", tolerate_missing=True
            )
        except Exception:
            _LOGGER.debug("Could not resolve the calling identity from the workspace", exc_info=True)
            return ""
        body = response or {}
        return str(body.get("userName") or body.get("id") or "").strip()


    ########################################################
    # src/databricks/labs/community_connector/sources/informix/sqli.py
    ########################################################

    def add_informix_exception_note(error: BaseException, note: str) -> None:
        # Docstring: Attach secondary diagnostics on every supported Python version.

        add_note = getattr(error, "add_note", None)
        if add_note is not None:
            add_note(note)
            return
        # Python 3.10 does not render PEP 678 notes, but exceptions have a writable
        # attribute dictionary. Preserve the same inspection contract for callers
        # and log the diagnostic so it remains visible in worker output.
        notes = getattr(error, "__notes__", None)
        if notes is None:
            notes = []
            error.__notes__ = notes
        notes.append(note)
        logging.getLogger(__name__).warning("%s", note)


    SQ_COMMAND = 1
    SQ_PREPARE = 2
    SQ_CURNAME = 3
    SQ_ID = 4
    SQ_OPEN = 6
    SQ_BIND = 5
    SQ_EXECUTE = 7
    SQ_NFETCH = 9
    SQ_CLOSE = 10
    SQ_RELEASE = 11
    SQ_EOT = 12
    SQ_ERR = 13
    SQ_DONE = 15
    SQ_NDESCRIBE = 22
    SQ_WANTDONE = 49
    SQ_DBOPEN = 36
    SQ_INFO = 81
    SQ_PROTOCOLS = 126
    SQ_EXIT = 56
    SQ_LODATA = 97
    SQ_RET_TYPE = 100
    SQ_INSERTDONE = 94
    SQ_ASSOC = 100
    SQ_ASCBINARY = 101
    SQ_ASCENV = 106
    SQ_ASCPINFO = 107
    SQ_ASCMISC_60 = 116
    SQ_ASCEOT = 127
    LO_READ = 0
    LO_READ_WITH_SEEK = 1
    TRANSFER_BUFFER_SIZE = 32000
    SQLI_PROTOCOL = 60
    INTERNAL_VERSION = 316
    PROTOCOL_OFFER = bytes.fromhex("ff fc 7f fc 3c 8c aa 97 06")
    MAX_PACKET = 16 * 1024 * 1024


    def _protocol_feature(bits: bytes, feature: int) -> bool:
        index, offset = divmod(feature, 8)
        return index < len(bits) and bool(bits[index] & (1 << (7 - offset)))


    class SqliProtocolError(RuntimeError):
        pass


    # These dataclasses turn off the generated __repr__ and __eq__: nothing prints them or
    # compares them by value, a repr would expose the password fields below, and the
    # merged deployment pickles every generated method.
    @dataclass(frozen=True, eq=False, repr=False)
    class InformixDatetimeLiteral:
        # Docstring: A canonical partial DATETIME value paired with its native qualifier.

        value: str
        qualifier: int


    class SqliTransportError(SqliProtocolError):
        # Docstring: A connection-specific SQLI failure that is safe to retry on another address.
        pass


    class SqliSessionRejected(SqliProtocolError):
        # Docstring: Informix rejected the SQLI session before authentication diagnostics.
        pass


    def informix_locale_encoding(locale: str | None) -> str:
        # Docstring: Return the verified Python codec for an Informix locale codeset.

        codeset = (locale or "en_US.utf8").rsplit(".", 1)[-1].lower()
        aliases = {
            "819": "iso8859-1",
            "iso8859-1": "iso8859-1",
            "iso-8859-1": "iso8859-1",
            "utf8": "utf-8",
            "utf-8": "utf-8",
            "57372": "utf-8",
        }
        try:
            return aliases[codeset]
        except KeyError as exc:
            raise SqliProtocolError(
                f"Unsupported Informix locale codeset {codeset!r}; configure a verified alias"
            ) from exc


    def _decode_text(raw: bytes, encoding: str) -> str:
        # Docstring: Decode a result string, turning a codeset mismatch into an actionable error.
        #
        # Informix converts result data from the database codeset to the client codeset
        # on the wire, so ``encoding`` is the CLIENT_LOCALE codec. A strict decode failure
        # almost always means CLIENT_LOCALE does not match what the server actually sent
        # (for example CLIENT_LOCALE left at en_US.utf8 while the server transmits Latin-1
        # for an en_US.819 database). Surface that as a clear diagnostic instead of a bare
        # UnicodeDecodeError so the fix -- align CLIENT_LOCALE with the source -- is obvious.

        try:
            return raw.decode(encoding)
        except UnicodeDecodeError as exc:
            raise SqliProtocolError(
                f"Could not decode an Informix result string as {encoding!r}; this usually "
                "means CLIENT_LOCALE does not match the codeset the server is sending "
                "(align CLIENT_LOCALE with the source database's DB_LOCALE)"
            ) from exc


    class SqliUnsupportedAuthentication(SqliProtocolError):
        pass


    class SqliRedirect(SqliUnsupportedAuthentication):
        def __init__(self, detail: str) -> None:
            super().__init__("Informix requested a connection redirect")
            self.detail = detail


    class SqliDescriptorNotImplemented(SqliProtocolError):
        pass


    class _DeadlineReader:
        # Docstring: Apply one absolute login deadline to every underlying stream read.

        def __init__(
            self, stream: BinaryIO, connection: socket.socket, deadline: float, maximum: float
        ) -> None:
            self._stream = stream
            self._connection = connection
            self._deadline: float | None = deadline
            self._maximum = maximum

        def read(self, size: int = -1) -> bytes:
            if self._deadline is not None:
                remaining = self._deadline - time.monotonic()
                if remaining <= 0:
                    raise SqliUnsupportedAuthentication("Informix login deadline exceeded")
                self._connection.settimeout(min(self._maximum, remaining))
            return self._stream.read(size)

        def finish(self) -> None:
            self._deadline = None
            self._connection.settimeout(self._maximum)

        def close(self) -> None:
            self._stream.close()


    class ConnectionState(Enum):
        NEW = auto()
        SOCKET_OPEN = auto()
        ASC_SENT = auto()
        ACCEPTED = auto()
        AUTHENTICATED = auto()
        DATABASE_OPEN = auto()
        POISONED = auto()
        CLOSED = auto()


    @dataclass(frozen=True, eq=False, repr=False)
    class AscAccept:
        version: str
        cap_1: int
        cap_2: int
        cap_3: int
        warnings: int


    @dataclass(frozen=True, eq=False, repr=False)
    class ResultColumn:
        name: str
        position: int
        type_code: int
        extended_id: int
        encoded_length: int
        extended_owner: str = ""
        extended_name: str = ""


    @dataclass(frozen=True, eq=False, repr=False)
    class ResultDescription:
        statement_type: int
        statement_id: int
        tuple_size: int
        columns: tuple[ResultColumn, ...]


    class AuthenticationProvider(Protocol):
        # Docstring: Noninteractive, secret-backed PAM response provider.

        def respond(self, style: int, challenge: str) -> str | bytes: ...


    @dataclass(frozen=True, eq=False, repr=False)
    class PasswordAuthenticationProvider:
        password: str
        echo_response: str | None = None

        def respond(self, style: int, challenge: str) -> str:
            del challenge
            if style == 1:
                return self.password
            if style == 2 and self.echo_response is not None:
                return self.echo_response
            raise SqliUnsupportedAuthentication(f"no noninteractive PAM response for style {style}")


    @dataclass(frozen=True, eq=False, repr=False)
    class TypedBind:
        native_type: int
        value: int | str | None


    def encode_bind(values: tuple[TypedBind, ...], encoding: str = "utf-8") -> bytes:
        if len(values) > 1024:
            raise ValueError("too many SQLI bind values")
        out = io.BytesIO()
        out.write(struct.pack(">hh", SQ_BIND, len(values)))
        for bind in values:
            out.write(struct.pack(">h", bind.native_type))
            if bind.native_type > 18 and bind.native_type not in {52, 53}:
                raise ValueError("extended bind types require owner/type metadata")
            if bind.value is None:
                out.write(struct.pack(">hh", -1, 0))
                continue
            if bind.native_type == 2:
                raw = struct.pack(">i", int(bind.value))
            elif bind.native_type in {52, 53}:
                raw = struct.pack(">q", int(bind.value))
            elif bind.native_type == 0:
                raw = str(bind.value).encode(encoding)
            elif bind.native_type == 13:
                text = str(bind.value).encode(encoding)
                if len(text) > 255:
                    raise ValueError("VARCHAR bind exceeds one-byte encoded length")
                raw = bytes([len(text)]) + text
            else:
                raise ValueError(f"unsupported internal bind type {bind.native_type}")
            if len(raw) > 32767:
                raise ValueError("bind value exceeds signed-smallint length")
            out.write(struct.pack(">hh", 0, len(raw)))
            out.write(raw)
            if len(raw) & 1:
                out.write(b"\0")
        return out.getvalue()


    def encode_pam_response(response: str, encoding: str = "utf-8") -> bytes:
        raw = response.encode(encoding)
        if len(raw) > 512:
            raise SqliUnsupportedAuthentication("PAM response exceeds 512-byte bound")
        return (
            struct.pack(">hh", 130, len(raw))
            + raw
            + (b"\0" if len(raw) & 1 else b"")
            + struct.pack(">h", SQ_EOT)
        )


    def parse_redirect_detail(detail: str, allowlist: set[tuple[str, int]]) -> tuple[str, str, int]:
        tokens = re.split(r"[:=|]", detail)
        if (
            len(tokens) not in {4, 5}
            or not tokens[-1].isdigit()
            or any(not token for token in tokens)
            or any(ord(char) < 0x20 or ord(char) == 0x7F for char in detail)
        ):
            raise SqliUnsupportedAuthentication("redirect detail has unsafe grammar")
        server, host, port = tokens[-3], tokens[-2], int(tokens[-1])
        if not re.fullmatch(r"[A-Za-z0-9_.-]+", server) or not re.fullmatch(r"[A-Za-z0-9.-]+", host):
            raise SqliUnsupportedAuthentication("redirect detail has unsafe identifiers")
        if not server or not host or not 1 <= port <= 65535 or (host, port) not in allowlist:
            raise SqliUnsupportedAuthentication("redirect target is not explicitly allow-listed")
        return server, host, port


    def encode_char(value: str | bytes, encoding: str = "utf-8") -> bytes:
        raw = value.encode(encoding) if isinstance(value, str) else bytes(value)
        if len(raw) > 0x7FFF:
            raise ValueError("SQLI CHAR exceeds signed-smallint length")
        return struct.pack(">h", len(raw)) + raw + (b"\0" if len(raw) & 1 else b"")


    def encode_asc_char(value: str | bytes, encoding: str = "utf-8") -> bytes:
        raw = value.encode(encoding) if isinstance(value, str) else bytes(value)
        if not raw.endswith(b"\0"):
            raw += b"\0"
        if len(raw) > 0x7FFF:
            raise ValueError("ASC string exceeds signed-smallint length")
        return struct.pack(">H", len(raw)) + raw


    def decode_char(stream: BinaryIO, encoding: str = "utf-8", maximum: int = 1 << 20) -> str:
        length = read_smallint(stream)
        if length < 0 or length > maximum:
            raise SqliProtocolError(f"invalid SQLI CHAR length {length}")
        raw = read_exact(stream, length)
        if length & 1:
            read_exact(stream, 1)
        return _decode_text(raw, encoding)


    def encode_session_packet(sl_type: int, payload: bytes, protocol: int = SQLI_PROTOCOL) -> bytes:
        total = len(payload) + 6
        if total > 0xFFFF:
            raise ValueError("SQLI session-layer packet exceeds uint16 length")
        if not 0 <= sl_type <= 0xFF or not 0 <= protocol <= 0xFF:
            raise ValueError("session type/protocol must fit uint8")
        return struct.pack(">HBBH", total, sl_type, protocol, 0) + payload


    def read_session_packet(stream: BinaryIO, maximum: int = 0xFFFF) -> tuple[int, int, bytes]:
        total, sl_type, protocol, flags = struct.unpack(">HBBH", read_exact(stream, 6))
        if total < 6 or total > maximum:
            raise SqliProtocolError(f"invalid session-layer length {total}")
        if flags not in {0, 0x1000}:
            raise SqliProtocolError(f"unsupported session-layer flags 0x{flags:04x}")
        return sl_type, protocol, read_exact(stream, total - 6)


    def decode_asc_accept(packet: bytes, encoding: str = "utf-8") -> AscAccept:
        sl_type, protocol, payload = read_session_packet(io.BytesIO(packet))
        if protocol != SQLI_PROTOCOL:
            raise SqliProtocolError(f"server selected unsupported SQLI protocol {protocol}")
        if sl_type == 3:
            raise SqliSessionRejected(
                "Informix rejected the SQLI session before returning a diagnostic; "
                "inspect the server log (connection exhaustion commonly reports SQLCODE -25571)"
            )
        if sl_type not in {2, 13} or len(payload) < 4:
            raise SqliProtocolError(f"unexpected ASC session-layer type {sl_type}")
        if struct.unpack_from(">hh", payload) != (SQ_ASSOC, SQ_ASCBINARY):
            raise SqliProtocolError("invalid ASC accepted markers")
        body = memoryview(payload[4:])
        cursor = _BufferCursor(body)
        cursor.skip(4)
        cursor.skip(cursor.smallint_length())
        if cursor.smallint() != 108:
            raise SqliProtocolError("ASC response is missing marker 108")
        cursor.skip(12)
        version_text = cursor.bytes(cursor.smallint_length()).decode("ascii", "strict").rstrip("\0")
        cursor.skip(cursor.smallint_length())
        cursor.skip(cursor.smallint_length())
        cap_1, cap_2, cap_3 = cursor.int32(), cursor.int32(), cursor.int32()
        cursor.skip(2)
        cursor.skip(cursor.smallint_length())
        cursor.skip(cursor.smallint_length())
        cursor.skip(24)
        result_type = cursor.smallint()
        warnings = 0
        if result_type == 102:
            cursor.skip(6)
            service_error, os_error, warnings = cursor.smallint(), cursor.smallint(), cursor.smallint()
            if service_error:
                raise SqliUnsupportedAuthentication(
                    f"Informix authentication failed ({service_error}/{os_error})"
                )
            # Live IDS appends bounded ASC server metadata blocks before ASCEOT.
            # Their contents are informational; type/protocol/service status above
            # controls acceptance. Require the exact final marker and consume all.
            trailing = cursor.bytes(cursor.remaining)
            if len(trailing) < 2 or trailing[-2:] != struct.pack(">h", SQ_ASCEOT):
                raise SqliProtocolError("ASC INITRESP metadata is missing final ASCEOT")
        elif result_type == 103:
            cursor.smallint()
            detail = cursor.char(encoding)
            if cursor.remaining:
                raise SqliProtocolError("ASC redirect has trailing bytes")
            raise SqliRedirect(detail)
        elif result_type != 127:
            raise SqliProtocolError(f"unknown ASC result type {result_type}")
        if cursor.remaining:
            raise SqliProtocolError(f"ASC response has {cursor.remaining} trailing bytes")
        if sl_type == 13:
            raise SqliProtocolError("redirect packet did not contain SQ_ASCDBLIST")
        return AscAccept(version_text, cap_1, cap_2, cap_3, warnings)


    class _BufferCursor:
        def __init__(self, data: memoryview):
            self.data, self.offset = data, 0

        @property
        def remaining(self) -> int:
            return len(self.data) - self.offset

        def bytes(self, size: int) -> bytes:
            if size < 0 or size > self.remaining:
                raise SqliProtocolError(f"bounded field length {size} exceeds {self.remaining}")
            result = bytes(self.data[self.offset : self.offset + size])
            self.offset += size
            return result

        def skip(self, size: int) -> None:
            self.bytes(size)

        def smallint(self) -> int:
            return struct.unpack(">h", self.bytes(2))[0]

        def smallint_length(self) -> int:
            value = self.smallint()
            if value < 0:
                raise SqliProtocolError(f"negative nested length {value}")
            return value

        def int32(self) -> int:
            return struct.unpack(">i", self.bytes(4))[0]

        def char(self, encoding: str) -> str:
            size = self.smallint_length()
            raw = self.bytes(size)
            return raw.rstrip(b"\0").decode(encoding)


    def encode_normal_auth_prefix(
        username: str,
        password: str,
        server_name: str,
        database: str,
        encoding: str = "utf-8",
    ) -> bytes:
        # Docstring: Encode the fixed ASC normal-password portion before the recovered ASC tail.
        #
        # Password bytes are plaintext; callers must place this packet inside TLS.

        del database  # part of the public signature; the prefix does not carry it
        out = io.BytesIO()
        out.write(struct.pack(">hhi", SQ_ASSOC, SQ_ASCBINARY, 61))
        out.write(encode_asc_char(b"IEEEM\0"))
        out.write(struct.pack(">h", 108))
        out.write(b"sqlexec\0\0\0\0\0")
        out.write(encode_asc_char(b"9.280\0"))
        out.write(encode_asc_char(b"RDS#R000000\0"))
        out.write(encode_asc_char(b"sqli\0"))
        out.write(struct.pack(">iii", INTERNAL_VERSION, 0, 0))
        out.write(struct.pack(">h", 1))
        out.write(encode_asc_char(username, encoding))
        out.write(encode_asc_char(password, encoding))
        out.write(b"ol\0\0\0\0\0\0")
        out.write(struct.pack(">i", 61))
        out.write(b"tlitcp\0\0")
        out.write(struct.pack(">ihhi", 1, 104, 11, 3))
        out.write(encode_asc_char(server_name, encoding))
        out.write(struct.pack(">h", 0))
        out.write(struct.pack(">hhhh", 0, 0, 0, 0))
        return out.getvalue()


    def encode_asc_environment(properties: dict[str, str], encoding: str = "utf-8") -> bytes:
        if len(properties) > 64:
            raise ValueError("too many ASC environment entries")
        out = io.BytesIO()
        out.write(struct.pack(">hh", SQ_ASCENV, len(properties)))
        for key, value in sorted(properties.items()):
            for item in (key, value):
                raw = item.encode(encoding)
                if not raw or len(raw) > 1023 or b"\0" in raw:
                    raise ValueError("invalid ASC environment key/value")
                out.write(struct.pack(">h", len(raw) + 1))
                out.write(raw + b"\0")
        return out.getvalue()


    def encode_asc_tail(
        properties: dict[str, str],
        hostname: str = "python-client",
        process_id: int = 0,
        thread_id: int = 0,
        cwd: str = "",
        diagnostic: str = "Thread[id:0, name:lakeflow, path:python]",
        encoding: str = "utf-8",
    ) -> bytes:
        out = io.BytesIO()
        out.write(encode_asc_environment(properties, encoding))
        out.write(struct.pack(">hiii", SQ_ASCPINFO, 0, process_id, thread_id))
        out.write(encode_asc_char(hostname, encoding))
        out.write(struct.pack(">h", 0))
        out.write(encode_asc_char(cwd, encoding))
        raw = diagnostic.encode("ascii")
        out.write(struct.pack(">hhiih", SQ_ASCMISC_60, 10 + len(raw) + 1, 0, 0, len(raw) + 1))
        out.write(raw + b"\0")
        out.write(struct.pack(">h", SQ_ASCEOT))
        return out.getvalue()


    def encode_normal_auth_request(
        username: str,
        password: str,
        server_name: str,
        database: str,
        properties: dict[str, str],
        encoding: str = "utf-8",
    ) -> bytes:
        prefix = encode_normal_auth_prefix(username, password, server_name, database, encoding)
        tail = encode_asc_tail(
            properties,
            hostname=socket.gethostname(),
            process_id=os.getpid(),
            thread_id=threading.get_ident() & 0x7FFFFFFF,
            cwd=os.getcwd(),
            encoding=encoding,
        )
        return encode_session_packet(1, prefix + tail)


    def _encode_sql_text(sql: str, encoding: str, long_length: bool) -> bytes:
        raw = sql.encode(encoding)
        maximum = 1 << 20 if long_length else 0x7FFF
        if not raw or len(raw) > maximum or b"\0" in raw:
            raise ValueError("invalid bounded SQL text")
        prefix = struct.pack(">i", len(raw)) if long_length else struct.pack(">h", len(raw))
        return prefix + raw + (b"\0" if len(raw) & 1 else b"")


    def encode_simple_command(
        sql: str, encoding: str = "utf-8", long_sql_length: bool = False
    ) -> bytes:
        if "\0" in sql:
            raise ValueError("SQL command contains NUL")
        return (
            struct.pack(">hh", SQ_COMMAND, 0)
            + _encode_sql_text(sql, encoding, long_sql_length)
            + struct.pack(">hhhh", SQ_NDESCRIBE, SQ_EXECUTE, SQ_RELEASE, SQ_EOT)
        )


    def encode_prepare(
        sql: str,
        encoding: str = "utf-8",
        parameter_count: int = 0,
        long_sql_length: bool = False,
    ) -> bytes:
        if not 0 <= parameter_count <= 1024:
            raise ValueError("parameter_count must be in [0, 1024]")
        return (
            struct.pack(">hh", SQ_PREPARE, parameter_count)
            + _encode_sql_text(sql, encoding, long_sql_length)
            + struct.pack(">hhh", SQ_NDESCRIBE, SQ_WANTDONE, SQ_EOT)
        )


    def encode_cursor_open(
        statement_id: int, cursor_name: str, encoding: str = "utf-8", binds: bytes = b""
    ) -> bytes:
        return (
            struct.pack(">hhh", SQ_ID, statement_id, SQ_CURNAME)
            + encode_char(cursor_name, encoding)
            + binds
            + struct.pack(">hh", SQ_OPEN, SQ_EOT)
        )


    def encode_fetch(statement_id: int, buffer_size: int = 32767) -> bytes:
        if not 1 <= buffer_size <= 32767:
            raise ValueError("fetch buffer_size must be in [1, 32767]")
        return struct.pack(">hhhihh", SQ_ID, statement_id, SQ_NFETCH, buffer_size, 0, SQ_EOT)


    def _effective_result_kind(column: ResultColumn) -> int:
        kind = column.type_code & 0xFF
        extended_owner = column.extended_owner.strip().upper()
        extended_name = column.extended_name.strip().upper()
        if kind == 40 and (extended_owner, extended_name) == ("INFORMIX", "LVARCHAR"):
            return 43
        if kind == 41 and (extended_owner, extended_name) == ("INFORMIX", "BOOLEAN"):
            return 45
        return kind


    def encode_variable_fetch(
        description: ResultDescription, buffer_size: int = 32767, encoding: str = "utf-8"
    ) -> bytes:
        # Docstring: Encode the two-phase variable-row RET_TYPE + NFETCH request.

        if not 1 <= buffer_size <= 32767:
            raise ValueError("fetch buffer_size must be in [1, 32767]")
        result = bytearray(
            struct.pack(
                ">hhhhh", SQ_ID, description.statement_id, SQ_RET_TYPE, 1, len(description.columns)
            )
        )
        for column in description.columns:
            native_kind = column.type_code & 0xFF
            kind = _effective_result_kind(column)
            if kind > 18 and kind not in {23, 43, 45, 52, 53}:
                raise SqliDescriptorNotImplemented(
                    f"variable result type {kind} requires an extended SQ_RET_TYPE name"
                )
            result.extend(struct.pack(">h", kind))
            if kind == 43:
                result.extend(encode_char("", encoding))
                result.extend(encode_char("", encoding))
            elif native_kind in {40, 41} and column.extended_id:
                if not column.extended_owner or not column.extended_name:
                    raise SqliDescriptorNotImplemented(
                        f"extended result type {native_kind} is missing owner/type metadata"
                    )
                result.extend(encode_char(column.extended_owner, encoding))
                result.extend(encode_char(column.extended_name, encoding))
            result.extend(struct.pack(">i", column.encoded_length))
        result.extend(struct.pack(">hihh", SQ_NFETCH, buffer_size, 0, SQ_EOT))
        return bytes(result)


    def encode_fixed_open_fetch(
        statement_id: int,
        cursor_name: str,
        binds: bytes = b"",
        encoding: str = "utf-8",
        buffer_size: int = 4096,
    ) -> bytes:
        if not 1 <= buffer_size <= 32767:
            raise ValueError("fetch buffer_size must be in [1, 32767]")
        return (
            struct.pack(">hhh", SQ_ID, statement_id, SQ_CURNAME)
            + encode_char(cursor_name, encoding)
            + binds
            + struct.pack(">hhhhihh", SQ_OPEN, SQ_ID, statement_id, SQ_NFETCH, buffer_size, 0, SQ_EOT)
        )


    def encode_close_release(statement_id: int, release: bool = False) -> bytes:
        operation = SQ_RELEASE if release else SQ_CLOSE
        return struct.pack(">hhhh", SQ_ID, statement_id, operation, SQ_EOT)


    def encode_protocol_offer() -> bytes:
        return (
            struct.pack(">hh", SQ_PROTOCOLS, len(PROTOCOL_OFFER))
            + PROTOCOL_OFFER
            + b"\0"
            + struct.pack(">h", SQ_EOT)
        )


    def encode_secondary_info(properties: dict[str, str], encoding: str = "utf-8") -> bytes:
        encoded = [
            (encode_char(k, encoding), encode_char(v, encoding)) for k, v in sorted(properties.items())
        ]
        max_key = max((len(item[0]) - 2 for item in encoded), default=0)
        max_value = max((len(item[1]) - 2 for item in encoded), default=0)
        total = 6 + sum(4 + len(key) - 2 + len(value) - 2 for key, value in encoded)
        if total > 0x7FFF:
            raise ValueError("secondary environment exceeds signed-smallint size")
        return (
            struct.pack(">hhhhh", SQ_INFO, 6, total, max_key, max_value)
            + b"".join(key + value for key, value in encoded)
            + struct.pack(">hhh", 0, 0, SQ_EOT)
        )


    def encode_dbopen(database: str, encoding: str = "utf-8") -> bytes:
        return (
            struct.pack(">h", SQ_DBOPEN)
            + encode_char(database, encoding)
            + struct.pack(">hh", 0, SQ_EOT)
        )


    def encode_lodata_read(descriptor: int, requested: int) -> bytes:
        if descriptor < -1 or descriptor > 0x7FFFFFFF:
            raise ValueError("SmartLOB descriptor must be >= -1 and fit signed int32")
        if requested < 1 or requested > 0x7FFFFFFF:
            raise ValueError("requested must be in [1, 2^31-1]")
        wire_descriptor = ((descriptor + 32768) % 65536) - 32768
        return struct.pack(
            ">hhhih", SQ_LODATA, LO_READ, wire_descriptor, requested, TRANSFER_BUFFER_SIZE
        )


    def read_exact(stream: BinaryIO, size: int) -> bytes:
        if size < 0 or size > MAX_PACKET:
            raise SqliProtocolError(f"unsafe exact-read size {size}")
        chunks = bytearray()
        while len(chunks) < size:
            chunk = stream.read(size - len(chunks))
            if not chunk:
                raise SqliTransportError(f"truncated SQLI stream: needed {size}, got {len(chunks)}")
            chunks.extend(chunk)
        return bytes(chunks)


    def read_smallint(stream: BinaryIO) -> int:
        return struct.unpack(">h", read_exact(stream, 2))[0]


    def read_int32(stream: BinaryIO) -> int:
        return struct.unpack(">i", read_exact(stream, 4))[0]


    def _retained_size(value: object, seen: set[int] | None = None) -> int:
        # Docstring: Estimate retained decoded-result memory without double counting objects.

        if seen is None:
            seen = set()
        identity = id(value)
        if identity in seen:
            return 0
        seen.add(identity)
        size = sys.getsizeof(value)
        if isinstance(value, dict):
            return size + sum(
                _retained_size(key, seen) + _retained_size(item, seen) for key, item in value.items()
            )
        if isinstance(value, (list, tuple, set, frozenset)):
            return size + sum(_retained_size(item, seen) for item in value)
        return size


    def _connector_sql(sql: str, parameters: tuple) -> str:
        # Docstring: Bind only connector-owned scalar values using strict SQL literals.

        result: list[str] = []
        parameter_index = 0
        index = 0
        quote = None
        while index < len(sql):
            character = sql[index]
            following = sql[index + 1] if index + 1 < len(sql) else ""
            if quote:
                result.append(character)
                if character == quote:
                    if following == quote:
                        result.append(following)
                        index += 1
                    else:
                        quote = None
                index += 1
                continue
            if character in {"'", '"'}:
                quote = character
                result.append(character)
                index += 1
                continue
            if character == "-" and following == "-":
                end = sql.find("\n", index + 2)
                end = len(sql) if end < 0 else end
                result.append(sql[index:end])
                index = end
                continue
            if character == "/" and following == "*":
                end = sql.find("*/", index + 2)
                if end < 0:
                    raise ValueError("unterminated connector SQL block comment")
                result.append(sql[index : end + 2])
                index = end + 2
                continue
            if character != "?":
                result.append(character)
                index += 1
                continue
            if parameter_index >= len(parameters):
                raise ValueError("SQL placeholder count does not match parameters")
            value = parameters[parameter_index]
            if isinstance(value, InformixDatetimeLiteral):
                literal = _partial_datetime_sql(value.value, value.qualifier)
            elif isinstance(value, bool):
                literal = "1" if value else "0"
            elif isinstance(value, int):
                literal = str(value)
            elif isinstance(value, Decimal):
                if not value.is_finite():
                    raise ValueError("Informix DECIMAL parameters must be finite")
                literal = format(value, "f")
                if len(literal) > 32767:
                    raise ValueError("Informix DECIMAL parameter exceeds SQL literal bound")
            elif isinstance(value, datetime):
                if value.tzinfo is not None:
                    raise ValueError("Informix DATETIME parameters must be timezone-free")
                fraction = value.microsecond // 10
                literal = f"DATETIME({value:%Y-%m-%d %H:%M:%S}.{fraction:05d}) " "YEAR TO FRACTION(5)"
            elif isinstance(value, date):
                # DATE(string) is interpreted through the session's DBDATE setting.
                # MDY uses numeric components and is therefore locale-independent.
                literal = f"MDY({value.month},{value.day},{value.year})"
            elif isinstance(value, str):
                if "\0" in value or len(value.encode("utf-8")) > 32767:
                    raise ValueError("unsafe connector SQL string literal")
                literal = "'" + value.replace("'", "''") + "'"
            else:
                raise TypeError(f"unsupported connector SQL value {type(value).__name__}")
            result.append(literal)
            parameter_index += 1
            index += 1
        if parameter_index != len(parameters):
            raise ValueError("SQL placeholder count does not match parameters")
        return "".join(result)


    _DATETIME_FIELD_NAMES = {
        0: "YEAR",
        2: "MONTH",
        4: "DAY",
        6: "HOUR",
        8: "MINUTE",
        10: "SECOND",
        11: "FRACTION(1)",
        12: "FRACTION(2)",
        13: "FRACTION(3)",
        14: "FRACTION(4)",
        15: "FRACTION(5)",
    }


    def _partial_datetime_sql(value: str, qualifier: int) -> str:
        start, end = (qualifier >> 8) & 0xF, qualifier & 0xF
        fields = [code for code in (0, 2, 4, 6, 8, 10) if start <= code <= min(end, 10)]
        if end > 10:
            fields.append(end)
        expected = [_DATETIME_FIELD_NAMES[code] for code in fields]
        if start == 6 and "=" not in value:
            base_fields = [code for code in fields if code <= 10]
            main, separator, fraction = value.partition(".")
            components = main.split(":")
            if (
                len(components) != len(base_fields)
                or any(len(component) != 2 or not component.isdigit() for component in components)
                or (end > 10 and (not separator or len(fraction) != end - 10 or not fraction.isdigit()))
                or (end <= 10 and separator)
            ):
                raise ValueError("TIME string does not match its Informix DATETIME qualifier")
            qualifier_sql = expected[0] if start == end else f"{expected[0]} TO {expected[-1]}"
            return f"DATETIME({value}) {qualifier_sql}"
        parts = value.split(":")
        if len(parts) != len(expected):
            raise ValueError("partial Informix DATETIME does not match its qualifier")
        values: list[str] = []
        for part, name in zip(parts, expected, strict=True):
            prefix = name + "="
            if not part.startswith(prefix):
                raise ValueError("partial Informix DATETIME does not match its qualifier")
            component = part[len(prefix) :]
            width = 4 if name == "YEAR" else int(name[-2]) if name.startswith("FRACTION") else 2
            if len(component) != width or not component.isdigit():
                raise ValueError("invalid partial Informix DATETIME component")
            values.append(component)

        payload = values[0]
        for previous, code, component in zip(fields[:-1], fields[1:], values[1:], strict=True):
            if code >= 11:
                separator = "."
            elif previous == 4 and code == 6:
                separator = " "
            elif code <= 4:
                separator = "-"
            else:
                separator = ":"
            payload += separator + component
        qualifier_sql = expected[0] if start == end else f"{expected[0]} TO {expected[-1]}"
        return f"DATETIME({payload}) {qualifier_sql}"


    def datetime_order_preserving_cast(column: str, qualifier: int) -> str | None:
        # Docstring: Return a fixed-width SQL text expression for chunking a DATETIME column.
        #
        # Incremental snapshot chunks a table with ``WHERE key > <value>`` ordered by
        # that key. Informix DATETIME keyset literals do not round-trip for every
        # qualifier, so instead of comparing the DATETIME natively this renders the
        # value as its canonical zero-padded text and the connector compares strings.
        #
        # Keyset pagination is complete as long as the SAME expression drives
        # ``ORDER BY``, the ``WHERE`` bound, and the stored cursor, and the string
        # order is a deterministic total order that agrees between Informix and
        # Python. It does not need to be chronological. Within one column every value
        # shares the declared qualifier, so casting the column IN ITS OWN qualifier
        # range yields a fixed-width, zero-padded string (``YYYY-MM-DD HH:MM:SS.fffff``
        # truncated to the qualifier's fields). Fixed width makes byte order stable
        # across collations, so a DATETIME key column of any contiguous qualifier can
        # be chunked — including HOUR-anchored TIME-of-day and DATE-only ranges, and
        # such a column combined lexicographically with non-DATETIME key columns.
        #
        # ``qualifier`` uses the connector's decoded layout: start field in bits
        # 8..11 and end field in bits 0..3, with field codes 0=YEAR, 2=MONTH, 4=DAY,
        # 6=HOUR, 8=MINUTE, 10=SECOND, 11..15=FRACTION(1..5).
        #
        # Returns ``None`` for a malformed qualifier so the caller can fall back
        # rather than risk skipped or duplicated chunk rows.

        start, end = (qualifier >> 8) & 0xF, qualifier & 0xF
        field_starts = {0, 2, 4, 6, 8, 10}
        if start not in field_starts or end < start or end > 15:
            return None
        # Canonical text fields present for this qualifier: whole date/time fields
        # from start up to min(end, SECOND), plus an optional trailing FRACTION.
        fields = [code for code in (0, 2, 4, 6, 8, 10) if start <= code <= min(end, 10)]
        if end > 10:
            fields.append(end)
        if not fields:
            return None

        def _field_chars(code: int) -> int:
            if code == 0:
                return 4  # YEAR is rendered as four digits
            if code <= 10:
                return 2  # MONTH..SECOND are two digits each
            return code - 10  # FRACTION(k) is k digits

        # First field has no separator; each later field adds one separator char
        # ("-", " ", ":", or ".") plus its digits.
        width = _field_chars(fields[0]) + sum(1 + _field_chars(code) for code in fields[1:])
        return f"CAST({column} AS CHAR({width}))"


    def _statement_keyword(sql: str) -> str:
        index = 0
        while True:
            while index < len(sql) and sql[index].isspace():
                index += 1
            if sql.startswith("--", index):
                newline = sql.find("\n", index + 2)
                if newline < 0:
                    return ""
                index = newline + 1
                continue
            if sql.startswith("/*", index):
                end = sql.find("*/", index + 2)
                if end < 0:
                    return ""
                index = end + 2
                continue
            break
        end = index
        while end < len(sql) and (sql[end].isalnum() or sql[end] == "_"):
            end += 1
        return sql[index:end].upper()


    _NON_ROW_STATEMENTS = frozenset(
        {
            "ALTER",
            "BEGIN",
            "COMMIT",
            "CREATE",
            "DELETE",
            "DROP",
            "GRANT",
            "INSERT",
            "MERGE",
            "RENAME",
            "REVOKE",
            "ROLLBACK",
            "SET",
            "TRUNCATE",
            "UPDATE",
        }
    )


    def _decode_result_value(
        data: bytes,
        column: ResultColumn,
        encoding: str,
        pad_varchar: bool = False,
        null_byte: str = "keep",
    ) -> object:
        # The snapshot/query path decodes CHAR/VARCHAR/LVARCHAR itself (below), so apply the
        # NUL sanitizer here as the CDC path does in decode_value. Numeric/metadata results
        # are unaffected -- apply_null_byte only touches strings that contain a NUL.
        return apply_null_byte(_decode_result_value_raw(data, column, encoding, pad_varchar), null_byte)


    def _decode_result_value_raw(
        data: bytes, column: ResultColumn, encoding: str, pad_varchar: bool = False
    ) -> object:
        kind = _effective_result_kind(column)
        if kind in {0, 15}:  # CHAR, NCHAR
            return _decode_text(data[: column.encoded_length], encoding).rstrip(" ")
        if kind == 1:
            value = struct.unpack(">h", data[:2])[0]
            return None if value == -(1 << 15) else value
        if kind in {2, 6}:
            value = struct.unpack(">i", data[:4])[0]
            return None if value == -(1 << 31) else value
        if kind == 3:
            if data[:8] == b"\xff" * 8:
                return None
            return struct.unpack(">d", data[:8])[0]
        if kind == 4:
            if data[:4] == b"\xff" * 4:
                return None
            return struct.unpack(">f", data[:4])[0]
        if kind in {5, 8}:
            precision, scale = (column.encoded_length >> 8) & 0xFF, column.encoded_length & 0xFF
            expected = (precision + (scale & 1) + 3) // 2
            return decode_packed_decimal(data[:expected], precision, scale)
        if kind == 7:
            value = struct.unpack(">i", data[:4])[0]
            return None if value == -(1 << 31) else date(1899, 12, 31) + timedelta(days=value)
        if kind in {13, 16}:
            if pad_varchar:
                return _decode_text(data[: column.encoded_length], encoding).rstrip(" \0")
            if not data:
                raise SqliProtocolError("truncated variable VARCHAR")
            size = data[0]
            if size + 1 > len(data):
                raise SqliProtocolError("VARCHAR length exceeds tuple column")
            if size == 1 and data[1] == 0:
                return None
            return _decode_text(data[1 : size + 1], encoding)
        if kind == 43:
            if len(data) < 5:
                raise SqliProtocolError("truncated variable LVARCHAR")
            marker = data[0]
            size = struct.unpack_from(">i", data, 1)[0]
            if size < 0 or size + 5 != len(data):
                raise SqliProtocolError("LVARCHAR length does not match tuple column")
            if marker == 1:
                if size != 0:
                    raise SqliProtocolError("null LVARCHAR has a non-empty payload")
                return None
            if marker != 0:
                raise SqliProtocolError(f"invalid LVARCHAR null marker {marker}")
            return _decode_text(data[5:], encoding)
        if kind in {17, 18}:
            type_name = "INT8" if kind == 17 else "SERIAL8"
            value, consumed = decode_value(memoryview(data), ColumnDescriptor(column.name, type_name))
            if consumed != 10:
                raise SqliProtocolError(f"{type_name} decoder consumed {consumed} bytes")
            return value
        if kind in {52, 53}:
            value = struct.unpack(">q", data[:8])[0]
            return None if value == -(1 << 63) else value
        if kind == 10:
            # Some descriptors carry the start/end qualifier in extended_id.  Live
            # Informix 15 ordinary SELECT descriptors instead use extended_id=0
            # and the syscolumns.collength layout in encoded_length: packed width
            # in the high byte, qualifier nibbles in the low byte (0x130f for YEAR
            # TO FRACTION(5)).  Normalize that fallback to the CDC extended-id
            # layout expected by the shared DATETIME decoder.
            qualifier = column.extended_id
            if qualifier == 0:
                encoded_qualifier = column.encoded_length & 0xFF
                qualifier = ((encoded_qualifier >> 4) << 8) | (encoded_qualifier & 0x0F)
            value, _ = decode_value(
                memoryview(data),
                ColumnDescriptor("datetime", "DATETIME", length=qualifier),
            )
            return value
        if kind == 14:
            return decode_interval(memoryview(data), column.encoded_length)[0]
        if kind == 45:
            if len(data) >= 5:
                envelope_size = struct.unpack_from(">i", data, 1)[0]
                if envelope_size < 0 or envelope_size + 5 != len(data):
                    raise SqliProtocolError("BOOLEAN envelope length does not match tuple column")
                null_marker = data[0]
                if null_marker == 1:
                    if envelope_size != 0:
                        raise SqliProtocolError("null BOOLEAN has a non-empty payload")
                    return None
                if null_marker != 0:
                    raise SqliProtocolError(f"invalid BOOLEAN envelope null marker {null_marker}")
                data = data[5:]
            if not data:
                raise SqliProtocolError("truncated BOOLEAN result")
            marker = struct.unpack_from(">b", data, 1 if len(data) >= 2 else 0)[0]
            if marker == -1:
                return None
            if marker in {1, ord("t"), ord("T")}:
                return True
            if marker in {0, ord("f"), ord("F")}:
                return False
            raise SqliProtocolError(f"invalid BOOLEAN result marker {marker}")
        raise SqliDescriptorNotImplemented(f"ordinary Informix result type {kind} is unsupported")


    def _fixed_result_size(column: ResultColumn) -> int:
        kind = column.type_code & 0xFF
        widths = {
            1: 2,
            2: 4,
            3: 8,
            4: 4,
            6: 4,
            7: 4,
            17: 10,
            18: 10,
            52: 8,
            53: 8,
        }
        if kind in {0, 15}:
            return column.encoded_length
        if kind in widths:
            return widths[kind]
        if kind in {5, 8}:
            precision, scale = (column.encoded_length >> 8) & 0xFF, column.encoded_length & 0xFF
            return (precision + (scale & 1) + 3) // 2
        if kind == 10:
            total, fraction = (column.encoded_length >> 8) & 0xFF, column.encoded_length & 0xFF
            return (total + (fraction & 1) + 3) // 2
        if kind == 14:
            layout = interval_layout(column.encoded_length)
            if layout is None:
                raise SqliProtocolError(f"invalid INTERVAL qualifier 0x{column.encoded_length:04x}")
            total = (column.encoded_length >> 8) & 0xFF
            return (total + (layout[2] & 1) + 3) // 2
        if kind == 45:
            if column.encoded_length not in {1, 2}:
                raise SqliProtocolError(
                    f"BOOLEAN result width must be 1 or 2, got {column.encoded_length}"
                )
            return column.encoded_length
        raise SqliDescriptorNotImplemented(f"ordinary Informix result type {kind} is unsupported")


    @dataclass(eq=False, repr=False)
    class InformixSqliClient:
        hostname: str
        port: int
        database: str
        user: str
        password: str
        server_name: str | None = None
        db_locale: str | None = "en_US.819"
        client_locale: str | None = "en_US.utf8"
        tls: bool = True
        ssl_context: ssl.SSLContext | None = None
        ca_file: str | None = None
        pad_varchar: bool = False
        # How a decoded string containing an embedded NUL is sanitized: "keep"/"null"/"empty"
        # (see cdc_protocol.apply_null_byte). The bridge sets this from the connection option.
        null_byte: str = "keep"
        connect_timeout: float = 10.0
        socket_timeout: float = 30.0
        authentication_mode: str = "password"
        authentication_provider: AuthenticationProvider | None = None
        pam_max_rounds: int = 16
        login_timeout: float = 30.0
        redirect_enabled: bool = False
        redirect_allowlist: frozenset[tuple[str, int]] = frozenset()
        redirect_max: int = 3
        state: ConnectionState = field(default=ConnectionState.NEW, init=False)
        remove_64k_limit: bool = field(default=False, init=False)
        large_tuple_size: bool = field(default=False, init=False)
        long_row_id: bool = field(default=False, init=False)
        bigint_supported: bool = field(default=False, init=False)
        _socket: socket.socket | None = field(default=None, init=False, repr=False)
        _input: BinaryIO | None = field(default=None, init=False, repr=False)
        _output: BinaryIO | None = field(default=None, init=False, repr=False)
        _lock: threading.Lock = field(default_factory=threading.Lock, init=False, repr=False)

        def connect(self) -> "InformixSqliClient":
            if not self.server_name:
                raise SqliUnsupportedAuthentication(
                    "server_name is required; DB_LOCALE defaults to en_US.819 and CLIENT_LOCALE "
                    "defaults to en_US.utf8; locale discovery, GSS and private-server "
                    "authentication are unsupported"
                )
            deadline = time.monotonic() + self.login_timeout
            host, port, server = self.hostname, self.port, self.server_name
            visited: set[tuple[str, str, int]] = set()
            redirects = 0
            while True:
                self._reset_connection_state()
                redirected = redirects > 0
                addresses = self._resolved_addresses(host, port) if redirected else (host,)
                self._validate_redirect_destination(
                    host, port, redirected=redirected, addresses=addresses
                )
                identity = (server, ",".join(addresses), port)
                if identity in visited:
                    raise SqliUnsupportedAuthentication("Informix redirect loop detected")
                visited.add(identity)
                try:
                    if redirected:
                        failures: list[OSError | SqliTransportError] = []
                        for address in addresses:
                            try:
                                self._connect_once(host, port, server, deadline, address)
                                break
                            except SqliRedirect:
                                raise
                            except SqliUnsupportedAuthentication:
                                raise
                            except (OSError, SqliTransportError) as error:
                                failures.append(error)
                                self._reset_connection_state()
                        else:
                            protocol_failure = next(
                                (error for error in failures if isinstance(error, SqliTransportError)),
                                None,
                            )
                            selected = protocol_failure or failures[-1]
                            for failure in failures:
                                if failure is not selected:
                                    add_informix_exception_note(
                                        selected,
                                        f"Another validated redirect address failed: "
                                        f"{type(failure).__name__}: {failure}",
                                    )
                            raise selected
                    else:
                        self._connect_once(host, port, server, deadline, None)
                    self.hostname, self.port, self.server_name = host, port, server
                    return self
                except SqliRedirect as redirect:
                    self._reset_connection_state()
                    if not self.redirect_enabled:
                        raise SqliUnsupportedAuthentication(
                            "Informix redirect is disabled"
                        ) from redirect
                    redirects += 1
                    if redirects > self.redirect_max:
                        raise SqliUnsupportedAuthentication(
                            "Informix redirect limit exceeded"
                        ) from redirect
                    server, host, port = parse_redirect_detail(
                        redirect.detail, set(self.redirect_allowlist)
                    )
                except Exception:
                    self._poison()
                    raise

        def _connect_once(
            self,
            host: str,
            port: int,
            server: str,
            deadline: float,
            validated_address: str | None = None,
        ) -> None:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise SqliUnsupportedAuthentication("Informix login deadline exceeded")
            raw = socket.create_connection(
                (validated_address or host, port), min(self.connect_timeout, remaining)
            )
            # Tracks whatever socket must be closed on failure: the raw socket until a
            # TLS wrap replaces it, so a makefile failure after a successful handshake
            # closes the wrapped socket rather than leaking it.
            connection = raw
            try:
                raw.settimeout(min(self.socket_timeout, max(0.001, deadline - time.monotonic())))
                raw.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
                if self.tls:
                    context = self.ssl_context or ssl.create_default_context(cafile=self.ca_file)
                    connection = context.wrap_socket(raw, server_hostname=host)
                self._socket = connection
                self._input = _DeadlineReader(
                    self._socket.makefile("rb", buffering=4096),
                    self._socket,
                    deadline,
                    self.socket_timeout,
                )
                self._output = self._socket.makefile("wb", buffering=4096)
            except BaseException as primary_error:
                try:
                    connection.close()
                except OSError as close_error:
                    add_informix_exception_note(
                        primary_error,
                        f"Closing the failed Informix socket also failed: {close_error}",
                    )
                raise
            self.state = ConnectionState.SOCKET_OPEN
            properties = {
                "CLIENT_LOCALE": self.client_locale,
                "CLNT_PAM_CAPABLE": "1",
                "DBPATH": ".",
                "DB_LOCALE": self.db_locale,
                # Honor double-quoted delimited identifiers so table/owner names with
                # characters that are not valid undelimited (e.g. "+") can be escaped.
                # Safe here because the connector's SQL uses single-quoted string
                # literals exclusively, so no literal is reinterpreted as an identifier.
                "DELIMIDENT": "1",
                "IFX_UPDDESC": "1",
                "NODEFDAC": "no",
            }
            try:
                request = encode_normal_auth_request(
                    self.user,
                    self.password,
                    server,
                    self.database,
                    properties,
                    self._encoding,
                )
                self._output.write(request)
                self._output.flush()
                self.state = ConnectionState.ASC_SENT
                header = read_exact(self._input, 6)
                total = struct.unpack_from(">H", header)[0]
                response = header + read_exact(self._input, total - 6)
                self.asc_accept = decode_asc_accept(response, self._encoding)
                self.state = ConnectionState.ACCEPTED
                self._output.write(encode_protocol_offer())
                self._output.flush()
                self.server_protocols = self._read_protocol_offer()
                self.remove_64k_limit = bool(self.server_protocols[7] & 0x02)
                self.large_tuple_size = bool(self.server_protocols[8] & 0x04)
                self.long_row_id = bool(self.server_protocols[8] & 0x02)
                self.bigint_supported = _protocol_feature(self.server_protocols, 54)
                pam_advertised = _protocol_feature(self.server_protocols, 44)
                if self.authentication_mode == "pam":
                    if not pam_advertised:
                        raise SqliUnsupportedAuthentication(
                            "PAM requested but server did not advertise it"
                        )
                    self._authenticate_pam(deadline)
                self._output.write(encode_secondary_info(properties, self._encoding))
                self._output.flush()
                self._read_status_group()
                self.state = ConnectionState.AUTHENTICATED
                self._output.write(encode_dbopen(self.database, self._encoding))
                self._output.flush()
                self._read_status_group(require_done=True)
                if isinstance(self._input, _DeadlineReader):
                    self._input.finish()
                self.state = ConnectionState.DATABASE_OPEN
            except SqliRedirect:
                raise

        def _authenticate_pam(self, deadline: float) -> None:
            if self._input is None or self._output is None or self.authentication_provider is None:
                raise SqliUnsupportedAuthentication("PAM requires a noninteractive response provider")
            # Send SQ_ACK then EOT together.  Informix waits for the
            # EOT before it starts the PAM conversation.
            self._output.write(struct.pack(">hh", 128, SQ_EOT))  # SQ_ACK, SQ_EOT
            self._output.flush()
            for _ in range(self.pam_max_rounds):
                if time.monotonic() >= deadline:
                    raise SqliUnsupportedAuthentication("PAM login deadline exceeded")
                code = read_smallint(self._input)
                if code == SQ_ASCEOT:  # SQ_ACCEPT aliases ASCEOT numerically
                    if read_smallint(self._input) != SQ_EOT:
                        raise SqliProtocolError("PAM accept is missing EOT")
                    return
                if code == SQ_EXIT:
                    self._output.write(struct.pack(">hh", SQ_EXIT, SQ_EOT))
                    self._output.flush()
                    raise SqliUnsupportedAuthentication("Informix rejected PAM authentication")
                if code != 129:
                    raise SqliProtocolError(f"unexpected PAM message {code}")
                style = read_smallint(self._input)
                length = read_smallint(self._input)
                if length < 0 or length > 512:
                    raise SqliProtocolError("invalid PAM challenge length")
                raw = read_exact(self._input, length)
                if length & 1:
                    read_exact(self._input, 1)
                if read_smallint(self._input) != SQ_EOT:
                    raise SqliProtocolError("PAM challenge is missing EOT")
                if style not in {1, 2, 3, 4}:
                    raise SqliProtocolError(f"unsupported PAM challenge style {style}")
                if style in {3, 4}:
                    continue
                challenge = raw.decode(self._encoding, "strict")
                response = self.authentication_provider.respond(style, challenge)
                if isinstance(response, bytes):
                    response_raw = response
                    if len(response_raw) > 512:
                        raise SqliUnsupportedAuthentication("PAM response exceeds 512-byte bound")
                    packet = (
                        struct.pack(">hh", 130, len(response_raw))
                        + response_raw
                        + (b"\0" if len(response_raw) & 1 else b"")
                        + struct.pack(">h", SQ_EOT)
                    )
                else:
                    packet = encode_pam_response(response, self._encoding)
                self._output.write(packet)
                self._output.flush()
            raise SqliUnsupportedAuthentication("PAM round limit exceeded")

        def _resolved_addresses(self, host: str, port: int) -> tuple[str, ...]:
            try:
                values = {
                    item[4][0] for item in socket.getaddrinfo(host, port, type=socket.SOCK_STREAM)
                }
            except OSError as exc:
                raise SqliUnsupportedAuthentication("redirect destination cannot be resolved") from exc
            if not values:
                raise SqliUnsupportedAuthentication("redirect destination has no addresses")
            return tuple(sorted(values))

        def _validate_redirect_destination(
            self,
            host: str,
            port: int,
            redirected: bool,
            addresses: tuple[str, ...] | None = None,
        ) -> None:
            if not redirected:
                return
            if (host, port) not in self.redirect_allowlist:
                raise SqliUnsupportedAuthentication("redirect target is not explicitly allow-listed")
            resolved = addresses if addresses is not None else self._resolved_addresses(host, port)
            for value in resolved:
                address = ipaddress.ip_address(value)
                if not address.is_global and (str(address), port) not in self.redirect_allowlist:
                    raise SqliUnsupportedAuthentication("redirect resolved to a non-public address")

        def _reset_connection_state(self) -> None:
            self.close()
            self.remove_64k_limit = self.large_tuple_size = self.long_row_id = False
            self.bigint_supported = False
            for name in ("asc_accept", "server_protocols"):
                if hasattr(self, name):
                    delattr(self, name)
            self.state = ConnectionState.NEW

        @property
        def _encoding(self) -> str:
            return informix_locale_encoding(self.client_locale)

        def _require_open(self) -> tuple[BinaryIO, BinaryIO]:
            if (
                self.state != ConnectionState.DATABASE_OPEN
                or self._input is None
                or self._output is None
            ):
                raise SqliProtocolError("SQLI database session is not open")
            return self._input, self._output

        def set_socket_timeout(self, timeout: float) -> None:
            # Docstring: Update the timeout used by the live SQLI socket.

            if not math.isfinite(timeout) or timeout <= 0:
                raise ValueError("socket timeout must be finite and positive")
            self.socket_timeout = timeout
            if self._socket is not None:
                self._socket.settimeout(timeout)

        def _read_protocol_offer(self) -> bytes:
            if self._input is None:
                raise SqliProtocolError("SQLI input is unavailable")
            code = read_smallint(self._input)
            if code != SQ_PROTOCOLS:
                raise SqliProtocolError(f"expected SQ_PROTOCOLS, received {code}")
            size = read_smallint(self._input)
            if size < 5 or size > 1024:
                raise SqliProtocolError(f"invalid enhanced protocol size {size}")
            value = read_exact(self._input, size)
            if size & 1:
                read_exact(self._input, 1)
            if read_smallint(self._input) != SQ_EOT:
                raise SqliProtocolError("enhanced protocol response is missing EOT")
            return value

        def _read_status_group(self, require_done: bool = False) -> None:
            if self._input is None:
                raise SqliProtocolError("SQLI input is unavailable")
            saw_done = False
            saw_description = False
            statement_type = None
            while True:
                code = read_smallint(self._input)
                if code in {SQ_EOT, SQ_EXIT}:
                    if require_done and not saw_done:
                        raise SqliProtocolError("status response reached EOT without SQ_DONE")
                    return
                if code == 55:  # SQ_COST
                    read_int32(self._input)
                    read_int32(self._input)
                    continue
                if code == 99:  # SQ_XACTSTAT
                    read_exact(self._input, 6)
                    continue
                if code == 8:  # SQ_DESCRIBE
                    if saw_description:
                        raise SqliProtocolError("duplicate SQ_DESCRIBE in status response")
                    description = self._read_description()
                    if description.columns:
                        raise SqliProtocolError("non-row command returned a row-producing SQ_DESCRIBE")
                    saw_description = True
                    statement_type = description.statement_type
                    continue
                if code == SQ_INSERTDONE:
                    if statement_type != 6:
                        raise SqliProtocolError("SQ_INSERTDONE arrived outside an INSERT")
                    self._read_insertdone()
                    continue
                if code == SQ_DONE:
                    self._read_done()
                    saw_done = True
                    continue
                if code == SQ_CLOSE:
                    continue
                if code == SQ_ERR:
                    error = self._read_error()
                    if error[0] != 100:
                        raise SqliProtocolError(
                            f"Informix SQL error {error[0]}/{error[1]} at {error[2]}: {error[3]}"
                        )
                    continue
                raise SqliProtocolError(f"unknown status response message {code}")

        def _read_done(self) -> tuple[int, int, int, int]:
            if self._input is None:
                raise SqliProtocolError("SQLI input is unavailable")
            warnings = read_smallint(self._input)
            if self.long_row_id:
                rows, row_id = struct.unpack(">qq", read_exact(self._input, 16))
            else:
                rows, row_id = read_int32(self._input), read_int32(self._input)
            serial = read_int32(self._input)
            return warnings, rows, row_id, serial

        def _read_insertdone(self) -> None:
            if self._input is None:
                raise SqliProtocolError("SQLI input is unavailable")
            # INT8 uses Informix's 10-byte signed-magnitude
            # representation; BIGSERIAL uses an 8-byte bigint.
            read_exact(self._input, 10)
            if self.bigint_supported:
                read_exact(self._input, 8)

        def _read_error(self) -> tuple[int, int, int, str]:
            if self._input is None:
                raise SqliProtocolError("SQLI input is unavailable")
            sqlcode, isamcode = read_smallint(self._input), read_smallint(self._input)
            statement_offset = (
                read_int32(self._input) if self.remove_64k_limit else read_smallint(self._input)
            )
            message = "" if sqlcode == -368 else decode_char(self._input, self._encoding)
            return sqlcode, isamcode, statement_offset, message

        def execute(
            self, sql: str, parameters: tuple = (), max_result_bytes: int | None = None
        ) -> list[tuple]:
            # Connector queries are fixed templates. Literalizing their bounded scalar
            # values avoids depending on the separate input-parameter descriptor that
            # the native protocol uses to choose VARCHAR bind widths.
            sql = _connector_sql(sql, parameters)
            if _statement_keyword(sql) in _NON_ROW_STATEMENTS:
                self.execute_command(sql)
                return []
            _, output_stream = self._require_open()
            typed: tuple[TypedBind, ...] = ()
            with self._lock:
                try:
                    output_stream.write(
                        encode_prepare(sql, self._encoding, len(typed), self.remove_64k_limit)
                    )
                    output_stream.flush()
                    description, rows, _ = self._read_query_group(None)
                    retained_bytes = _retained_size(rows) if max_result_bytes is not None else 0

                    def append_batch(batch: list[dict[str, object]]) -> None:
                        nonlocal retained_bytes
                        if max_result_bytes is not None:
                            retained_bytes += _retained_size(batch)
                        if max_result_bytes is not None and retained_bytes > max_result_bytes:
                            raise SqliProtocolError(
                                f"SQLI result exceeded max_result_bytes={max_result_bytes}"
                            )
                        rows.extend(batch)

                    if max_result_bytes is not None and retained_bytes > max_result_bytes:
                        raise SqliProtocolError(
                            f"SQLI result exceeded max_result_bytes={max_result_bytes}"
                        )
                    if description is None:
                        return rows
                    cursor_name = f"lc_{description.statement_id}"
                    binds = encode_bind(typed, self._encoding) if typed else b""
                    variable = not self.pad_varchar and any(
                        (column.type_code & 0xFF) in {13, 16, 40, 41, 43, 46}
                        for column in description.columns
                    )
                    if variable:
                        output_stream.write(
                            encode_cursor_open(
                                description.statement_id, cursor_name, self._encoding, binds
                            )
                        )
                        output_stream.flush()
                        self._read_query_group(description)
                        output_stream.write(encode_variable_fetch(description, encoding=self._encoding))
                        output_stream.flush()
                        _, batch, exhausted = self._read_query_group(description)
                        append_batch(batch)
                        if exhausted:
                            return self._close_query(description, rows, output_stream)
                    else:
                        output_stream.write(
                            encode_fixed_open_fetch(
                                description.statement_id,
                                cursor_name,
                                binds,
                                self._encoding,
                                4096,
                            )
                        )
                        output_stream.flush()
                        _, batch, exhausted = self._read_query_group(description)
                        append_batch(batch)
                        if exhausted:
                            return self._close_query(description, rows, output_stream)
                    while True:
                        output_stream.write(encode_fetch(description.statement_id))
                        output_stream.flush()
                        _, batch, exhausted = self._read_query_group(description)
                        append_batch(batch)
                        if exhausted:
                            break
                    output_stream.write(encode_close_release(description.statement_id))
                    output_stream.flush()
                    self._read_query_group(description)
                    output_stream.write(encode_close_release(description.statement_id, release=True))
                    output_stream.flush()
                    self._read_query_group(description)
                    return rows
                except Exception:
                    self._poison()
                    raise

        def execute_pages(
            self,
            sql: str,
            parameters: tuple,
            page_size: int,
            page_consumer: Callable[[list[dict[str, object]]], None],
        ) -> None:
            # Docstring: Stream one SELECT through one forward-only cursor in bounded pages.

            if page_size < 1:
                raise ValueError("page_size must be positive")
            sql = _connector_sql(sql, parameters)
            if _statement_keyword(sql) in _NON_ROW_STATEMENTS:
                raise ValueError("execute_pages requires a row-producing statement")
            _, output_stream = self._require_open()
            typed: tuple[TypedBind, ...] = ()
            pending: list[dict[str, object]] = []

            def consume(batch: list[dict[str, object]]) -> None:
                pending.extend(batch)
                while len(pending) >= page_size:
                    page = pending[:page_size]
                    del pending[:page_size]
                    page_consumer(page)

            with self._lock:
                try:
                    output_stream.write(
                        encode_prepare(sql, self._encoding, len(typed), self.remove_64k_limit)
                    )
                    output_stream.flush()
                    description, initial, _ = self._read_query_group(None)
                    consume(initial)
                    if description is None:
                        if pending:
                            page_consumer(pending)
                        return
                    cursor_name = f"lc_{description.statement_id}"
                    variable = not self.pad_varchar and any(
                        (column.type_code & 0xFF) in {13, 16, 40, 41, 43, 46}
                        for column in description.columns
                    )
                    if variable:
                        output_stream.write(
                            encode_cursor_open(
                                description.statement_id, cursor_name, self._encoding, b""
                            )
                        )
                        output_stream.flush()
                        self._read_query_group(description)
                        output_stream.write(encode_variable_fetch(description, encoding=self._encoding))
                    else:
                        output_stream.write(
                            encode_fixed_open_fetch(
                                description.statement_id,
                                cursor_name,
                                b"",
                                self._encoding,
                                4096,
                            )
                        )
                    output_stream.flush()
                    _, batch, exhausted = self._read_query_group(description)
                    consume(batch)
                    while not exhausted:
                        output_stream.write(encode_fetch(description.statement_id))
                        output_stream.flush()
                        _, batch, exhausted = self._read_query_group(description)
                        consume(batch)
                    output_stream.write(encode_close_release(description.statement_id))
                    output_stream.flush()
                    self._read_query_group(description)
                    output_stream.write(encode_close_release(description.statement_id, release=True))
                    output_stream.flush()
                    self._read_query_group(description)
                    if pending:
                        page_consumer(pending)
                except Exception:
                    self._poison()
                    raise

        def execute_command(self, sql: str) -> None:
            # Docstring: Execute a connector-owned non-row SQL statement through SQ_COMMAND.

            _, output_stream = self._require_open()
            with self._lock:
                try:
                    output_stream.write(
                        encode_simple_command(sql, self._encoding, self.remove_64k_limit)
                    )
                    output_stream.flush()
                    self._read_status_group(require_done=True)
                except Exception:
                    self._poison()
                    raise

        def _close_query(self, description, rows, output_stream):
            output_stream.write(encode_close_release(description.statement_id))
            output_stream.flush()
            self._read_query_group(description)
            output_stream.write(encode_close_release(description.statement_id, release=True))
            output_stream.flush()
            self._read_query_group(description)
            return rows

        def _read_query_group(
            self, description: ResultDescription | None
        ) -> tuple[ResultDescription | None, list[dict[str, object]], bool]:
            if self._input is None:
                raise SqliProtocolError("SQLI input is unavailable")
            rows, exhausted = [], False
            while True:
                code = read_smallint(self._input)
                if code in {SQ_EOT, SQ_EXIT}:
                    return description, rows, exhausted
                if code == 8:
                    if description is not None:
                        raise SqliProtocolError("duplicate SQ_DESCRIBE")
                    description = self._read_description()
                elif code == 14:
                    if description is None:
                        raise SqliProtocolError("SQ_TUPLE arrived before SQ_DESCRIBE")
                    rows.append(self._read_tuple(description))
                elif code == SQ_ERR:
                    error = self._read_error()
                    if error[0] == 100:
                        exhausted = True
                    else:
                        raise SqliProtocolError(
                            f"Informix SQL error {error[0]}/{error[1]} at {error[2]}: {error[3]}"
                        )
                elif code == 55:
                    read_exact(self._input, 8)
                elif code == 99:
                    read_exact(self._input, 6)
                elif code == SQ_INSERTDONE:
                    if description is None or description.statement_type != 6:
                        raise SqliProtocolError("SQ_INSERTDONE arrived outside an INSERT")
                    self._read_insertdone()
                elif code == SQ_DONE:
                    _, affected_rows, _, _ = self._read_done()
                    # A forward-only fetch that has no more tuples is reported as
                    # SQ_DONE(rows=0) by IDS 15 (the accompanying zero row id
                    # corresponds to the SQLSTATE-02000/end-of-data warning).
                    if description is not None and (affected_rows == 0 or not rows):
                        exhausted = True
                elif code == SQ_CLOSE:
                    # Informix may close a forward-only cursor in the same group as
                    # the final tuple instead of emitting SQLCODE 100.  Track this
                    # as a received close and do not issue another NFETCH.
                    exhausted = True
                else:
                    raise SqliProtocolError(f"unknown query response message {code}")

        def _read_description(self) -> ResultDescription:
            if self._input is None:
                raise SqliProtocolError("SQLI input is unavailable")
            statement_type, statement_id = read_smallint(self._input), read_smallint(self._input)
            read_int32(self._input)  # optimizer row estimate
            tuple_size = (
                read_int32(self._input) if self.large_tuple_size else read_smallint(self._input)
            )
            count = read_smallint(self._input)
            name_size = read_int32(self._input)
            tuple_limit = MAX_PACKET if self.large_tuple_size else 32767
            if tuple_size < 0 or tuple_size > tuple_limit or count < 0 or count > 1024:
                raise SqliProtocolError("unsafe result description bounds")
            raw = []
            for _ in range(count):
                read_int32(self._input)
                position = read_int32(self._input)
                type_code = read_smallint(self._input)
                extended_id = read_int32(self._input)
                extended_owner = decode_char(self._input, self._encoding)
                extended_name = decode_char(self._input, self._encoding)
                read_smallint(self._input)
                read_smallint(self._input)
                read_int32(self._input)
                encoded_length = read_int32(self._input)
                if (
                    position < 0
                    or position > tuple_size
                    or encoded_length < 0
                    # Variable-width descriptors carry their declared maximum,
                    # which may exceed the current tuple's encoded size.
                    or encoded_length > tuple_limit
                ):
                    raise SqliProtocolError("invalid result column position/length")
                raw.append(
                    (
                        position,
                        type_code,
                        extended_id,
                        encoded_length,
                        extended_owner,
                        extended_name,
                    )
                )
            if name_size < 0 or name_size > 1 << 20:
                raise SqliProtocolError(f"unsafe descriptor name blob length {name_size}")
            names_raw = read_exact(self._input, name_size)
            if name_size & 1:
                read_exact(self._input, 1)
            names = (
                []
                if count == 0 and not names_raw
                else [item.decode(self._encoding) for item in names_raw.rstrip(b"\0").split(b"\0")]
            )
            if len(names) != count or len(set(names)) != count:
                raise SqliProtocolError("descriptor names do not match column count")
            columns = tuple(ResultColumn(name, *descriptor) for name, descriptor in zip(names, raw))
            if any(b.position < a.position for a, b in zip(columns, columns[1:])):
                raise SqliProtocolError("result column positions are not monotonic")
            return ResultDescription(statement_type, statement_id, tuple_size, columns)

        def _read_tuple(self, description: ResultDescription) -> dict[str, object]:
            if self._input is None:
                raise SqliProtocolError("SQLI input is unavailable")
            read_smallint(self._input)  # tuple warning
            size = read_int32(self._input)
            tuple_limit = MAX_PACKET if self.large_tuple_size else 32767
            if size < 0 or size > tuple_limit:
                raise SqliProtocolError(f"unsafe tuple payload length {size}")
            payload = read_exact(self._input, size)
            if size & 1:
                read_exact(self._input, 1)
            result = {}
            variable_layout = any(
                (column.type_code & 0xFF) in {40, 41, 43, 46}
                or (not self.pad_varchar and (column.type_code & 0xFF) in {13, 16})
                for column in description.columns
            )
            cursor = 0
            for index, column in enumerate(description.columns):
                kind = _effective_result_kind(column)
                start = cursor if variable_layout else column.position
                if variable_layout and kind in {13, 16}:
                    if self.pad_varchar:
                        limit = start + column.encoded_length
                    else:
                        if start >= len(payload):
                            raise SqliProtocolError("truncated variable VARCHAR tuple")
                        limit = start + 1 + payload[start]
                elif variable_layout and kind in {40, 41, 43, 45, 46}:
                    if start + 5 > len(payload):
                        raise SqliProtocolError("truncated complex variable tuple")
                    limit = start + 5 + struct.unpack_from(">i", payload, start + 1)[0]
                elif variable_layout:
                    limit = start + _fixed_result_size(column)
                else:
                    limit = (
                        description.columns[index + 1].position
                        if index + 1 < len(description.columns)
                        else len(payload)
                    )
                if not 0 <= start <= limit <= len(payload):
                    raise SqliProtocolError(
                        f"tuple column {column.name!r} slice [{start}:{limit}] "
                        f"exceeds payload size {len(payload)}"
                    )
                result[column.name] = _decode_result_value(
                    payload[start:limit], column, self._encoding, self.pad_varchar, self.null_byte
                )
                cursor = limit
            return result

        def read_lodata(self, descriptor: int, requested: int) -> bytes:
            input_stream, output_stream = self._require_open()
            with self._lock:
                try:
                    output_stream.write(encode_lodata_read(descriptor, requested))
                    output_stream.write(struct.pack(">h", SQ_EOT))
                    output_stream.flush()
                    chunks = bytearray()
                    while True:
                        code = read_smallint(input_stream)
                        if code == SQ_EOT:
                            return bytes(chunks)
                        if code == SQ_LODATA:
                            operation, size = read_smallint(input_stream), read_int32(input_stream)
                            if operation not in {LO_READ, LO_READ_WITH_SEEK}:
                                raise SqliProtocolError(
                                    f"unexpected SQ_LODATA response operation {operation}"
                                )
                            if size < 0:
                                raise SqliProtocolError(f"SQ_LODATA server/ISAM error {size}")
                            if size < 1:
                                read_smallint(input_stream)
                                continue
                            if len(chunks) + size > requested:
                                raise SqliProtocolError("SQ_LODATA response exceeds requested bound")
                            remaining = size
                            while remaining:
                                chunk_size = read_smallint(input_stream)
                                if chunk_size <= 0 or chunk_size > remaining:
                                    raise SqliProtocolError(
                                        f"invalid SQ_LODATA chunk size {chunk_size}"
                                    )
                                chunks.extend(read_exact(input_stream, chunk_size))
                                if chunk_size & 1:
                                    read_exact(input_stream, 1)
                                remaining -= chunk_size
                            continue
                        if code == SQ_ERR:
                            error = self._read_error()
                            raise SqliProtocolError(
                                f"Informix SQL error {error[0]}/{error[1]} "
                                f"at {error[2]} during LODATA: {error[3]}"
                            )
                        raise SqliProtocolError(f"unexpected SQLI message {code} during LODATA")
                except Exception:
                    self._poison()
                    raise

        def _poison(self) -> None:
            self.close()
            self.state = ConnectionState.POISONED

        def close(self) -> None:
            if self.state == ConnectionState.DATABASE_OPEN and self._output is not None:
                try:
                    self._output.write(struct.pack(">hh", SQ_EXIT, SQ_EOT))
                    self._output.flush()
                except (OSError, ValueError):
                    # Closing the underlying streams remains the fallback for a
                    # broken transport; graceful exit is best effort.
                    pass
            for stream in (self._input, self._output):
                if stream is not None:
                    try:
                        stream.close()
                    except OSError:
                        pass
            if self._socket is not None:
                try:
                    self._socket.close()
                except OSError:
                    pass
            self._input = self._output = None
            self._socket = None
            if self.state != ConnectionState.POISONED:
                self.state = ConnectionState.CLOSED


